  FT["SG-H2533"] = {"id":"SG-H2533","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S989-2020?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（ST Engineering 航空资源私人有限公司——第 13(12) 条豁免）命令 2020","en":"Income Tax (ST Engineering Aerospace Resources Pte. Ltd. — Section 13(12) Exemption) Order 2020","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S989-2020","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2533-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order is the Income Tax (ST Engineering Aerospace Resources Pte. Ltd. — Section 13(12) Exemption) Order 2020."}},{"id":"SG-H2533-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2.—(1) Dividends received in Singapore by ST Engineering Aerospace Resources Pte. Ltd. (a company incorporated in Singapore) in the basis periods for the year of assessment 2021 and subsequent years of assessment from the following companies which are incorporated in Ireland, are exempt from tax:\n(a)Capella 1 Leasing Limited;\n(b)Capella 2 Leasing Limited.\n(2) The exemption in sub‑paragraph (1) is subject to the conditions specified in the letter of approval dated 13 October 2020 addressed to KPMG Services Pte. Ltd."}}],"pack":"sg-p32","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (ST Engineering Aerospace Resources Pte. Ltd. — Section 13(12) Exemption) Order 2020","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2534"] = {"id":"SG-H2534","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S811-2022?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":13,"structureMode":"ARTICLE","title":{"zh":"所得税（Steppe Capital 私人有限公司——第 13（12）条豁免）命令 2022","en":"Income Tax (Steppe Capital Pte Ltd — Section 13(12) Exemption) Order 2022","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S811-2022","completenessNote":"全文，共 13 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。附表 5 篇以 900000+ 序号随同收录。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2534-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order is the Income Tax (Steppe Capital Pte Ltd — Section 13(12) Exemption) Order 2022."}},{"id":"SG-H2534-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Definitions"},"text":{"en":"2. In this Order —\n“Co-operative” means Steppe Unity Cooperatief U.A. incorporated in the Netherlands;\n“Holding Company” means any of the following companies incorporated in the Netherlands:\n(a)KazStroyService Infrastructure B.V.;\n(b)Venus Airport Holdings B.V.;\n(c)Aquila Properties Holdings B.V.;\n(d)Asset Estate Holdings B.V."}},{"id":"SG-H2534-A3","no":3,"noLabel":{"en":"3."},"heading":{"en":"Exemption for income received between 5 December 2011 and 6 August 2013"},"text":{"en":"3.—(1) The income received in Singapore by Steppe Capital Pte Ltd, comprising distributions from the Co‑operative or dividends from any Holding Company, is exempt from tax if the income is —\n(a)so received between 5 December 2011 and 6 August 2013 (both dates inclusive); and\n(b)derived by Steppe Capital Pte Ltd through the holding structures described in the letter dated 4 July 2012 from the tax agent of Steppe Capital Pte Ltd to the Inland Revenue Authority of Singapore (as amended by the electronic message of 4 September 2012 from the tax agent).\n(2) The exemption in sub‑paragraph (1) does not apply to any distribution or dividend declared out of the income of the Co‑operative or Holding Company (as the case may be) that is directly or indirectly derived from an ultimate entity.\n(3) For the purposes of sub‑paragraph (2), the income of an entity (A) is indirectly derived from another entity (B) if the income of A is derived from another entity whose income is in turn directly or indirectly derived (including by one or more applications of this sub‑paragraph) from B.\n(4) The exemption in sub‑paragraph (1) is subject to the terms and conditions specified in paragraphs 4 and 5 of the letter of approval dated 25 February 2013 addressed to the tax agent of Steppe Capital Pte Ltd.\n(5) In this paragraph, “ultimate entity” means an entity that is set out in the First Schedule."}},{"id":"SG-H2534-A4","no":4,"noLabel":{"en":"4."},"heading":{"en":"Exemption for income received between 7 August 2013 and 2 February 2015"},"text":{"en":"4.—(1) The income received in Singapore by Steppe Capital Pte Ltd, comprising distributions from the Co‑operative or dividends from any Holding Company, is exempt from tax if the income is —\n(a)so received between 7 August 2013 and 2 February 2015 (both dates inclusive); and\n(b)derived by Steppe Capital Pte Ltd through the holding structures described in the letter of approval dated 14 May 2014 addressed to Steppe Capital Pte Ltd.\n(2) The exemption in sub‑paragraph (1) does not apply to any distribution or dividend declared out of the income of the Co‑operative or Holding Company (as the case may be) that is directly or indirectly derived from an ultimate entity.\n(3) For the purposes of sub‑paragraph (2), the income of an entity (A) is indirectly derived from another entity (B) if the income of A is derived from another entity whose income is in turn directly or indirectly derived (including by one or more applications of this sub‑paragraph) from B.\n(4) The exemption in sub‑paragraph (1) is subject to the terms and conditions specified in paragraphs 4 and 5 of the letter of approval dated 25 February 2013 addressed to the tax agent of Steppe Capital Pte Ltd, which are incorporated by reference in paragraph 6 of the letter of approval dated 14 May 2014 addressed to Steppe Capital Pte Ltd.\n(5) In this paragraph, “ultimate entity” means an entity that is set out in the Second Schedule."}},{"id":"SG-H2534-A5","no":5,"noLabel":{"en":"5."},"heading":{"en":"Exemption for income received between 3 February 2015 and 2 August 2017"},"text":{"en":"5.—(1) The income received in Singapore by Steppe Capital Pte Ltd, comprising distributions from the Co‑operative or dividends from any Holding Company, is exempt from tax if the income is —\n(a)so received between 3 February 2015 and 2 August 2017 (both dates inclusive); and\n(b)derived by Steppe Capital Pte Ltd through the holding structures described in the letter of approval dated 2 March 2016 addressed to Steppe Capital Pte Ltd.\n(2) The exemption in sub‑paragraph (1) does not apply to any distribution or dividend declared out of the income of the Co‑operative or Holding Company (as the case may be) that is directly or indirectly derived from an ultimate entity.\n(3) For the purposes of sub-paragraph (2), the income of an entity (A) is indirectly derived from another entity (B) if the income of A is derived from another entity whose income is in turn directly or indirectly derived (including by one or more applications of this sub‑paragraph) from B.\n(4) The exemption in sub‑paragraph (1) is subject to the terms and conditions specified in —\n(a)paragraph 9 of the letter of approval dated 2 March 2016 addressed to Steppe Capital Pte Ltd; and\n(b)paragraphs 4 and 5 of the letter of approval dated 25 February 2013 addressed to the tax agent of Steppe Capital Pte Ltd, which are incorporated by reference in paragraph 10 of the letter of approval dated 2 March 2016 addressed to Steppe Capital Pte Ltd.\n(5) In this paragraph, “ultimate entity” means an entity that is set out in the Third Schedule."}},{"id":"SG-H2534-A6","no":6,"noLabel":{"en":"6."},"heading":{"en":"Exemption for income received between 3 August 2017 and 19 November 2017"},"text":{"en":"6.—(1) The income received in Singapore by Steppe Capital Pte Ltd, comprising distributions from the Co-operative or dividends from any Holding Company, is exempt from tax if the income is —\n(a)so received between 3 August 2017 and 19 November 2017 (both dates inclusive); and\n(b)derived by Steppe Capital Pte Ltd through the holding structures described in the letter of approval dated 3 August 2018 addressed to Steppe Capital Pte Ltd.\n(2) The exemption in sub‑paragraph (1) does not apply to any distribution or dividend declared out of the income of the Co‑operative or Holding Company (as the case may be) that is directly or indirectly derived from an ultimate entity.\n(3) For the purposes of sub‑paragraph (2), the income of an entity (A) is indirectly derived from another entity (B) if the income of A is derived from another entity whose income is in turn directly or indirectly derived (including by one or more applications of this sub‑paragraph) from B.\n(4) The exemption in sub‑paragraph (1) is subject to the terms and conditions specified in paragraphs 6 and 7 of the letter of approval dated 3 August 2018 addressed to Steppe Capital Pte Ltd.\n(5) In this paragraph, “ultimate entity” means an entity that is set out in the Fourth Schedule."}},{"id":"SG-H2534-A7","no":7,"noLabel":{"en":"7."},"heading":{"en":"Exemption for income received on or after 20 November 2017"},"text":{"en":"7.—(1) The income received in Singapore by Steppe Capital Pte Ltd, comprising distributions from the Co‑operative or dividends from any Holding Company, is exempt from tax if the income is —\n(a)so received on or after 20 November 2017; and\n(b)derived by Steppe Capital Pte Ltd through the holding structures described in the letter of approval dated 3 December 2020 addressed to Steppe Capital Pte Ltd.\n(2) The exemption in sub‑paragraph (1) does not apply to any distribution or dividend declared out of the income of the Co‑operative or Holding Company (as the case may be) that is directly or indirectly derived from an ultimate entity.\n(3) For the purposes of sub‑paragraph (2), the income of an entity (A) is indirectly derived from another entity (B) if the income of A is derived from another entity whose income is in turn directly or indirectly derived (including by one or more applications of this sub‑paragraph) from B.\n(4) The exemption in sub‑paragraph (1) is subject to the terms and conditions specified in paragraphs 5 and 6 of the letter of approval dated 3 December 2020 addressed to Steppe Capital Pte Ltd.\n(5) In this paragraph, “ultimate entity” means an entity that is set out in the Fifth Schedule."}},{"id":"SG-H2534-A8","no":8,"noLabel":{"en":"8."},"heading":{"en":"Revocation"},"text":{"en":"8. The Income Tax (Exemption of Foreign Income) (No. 6) Order 2013 (G.N. No. S 404/2013) is revoked."}},{"id":"SG-H2534-A900000","no":900000,"noLabel":{"en":"FIRST SCHEDULE"},"text":{"en":"FIRST SCHEDULE\nParagraph 3(5)\nUltimate entities\n1. KazStroyService Management Services Pte Ltd\n2. BKG Jersey Ltd\n3. Astana KZ National Combined KVN Team Corporate Fund"}},{"id":"SG-H2534-A900001","no":900001,"noLabel":{"en":"SECOND SCHEDULE"},"text":{"en":"SECOND SCHEDULE\nParagraph 4(5)\nUltimate entities\n1. KazStroyService Management Services Pte Ltd\n2. BKG Jersey Ltd\n3. Golden Steppe LLP\n4. Service Pipes Holdings LLP\n5. Sumeru LLP\n6. Astana KZ National Combined KVN Team Corporate Fund\n7. Express Consulting LLP"}},{"id":"SG-H2534-A900002","no":900002,"noLabel":{"en":"THIRD SCHEDULE"},"text":{"en":"THIRD SCHEDULE\nParagraph 5(5)\nUltimate entities\n1. KazStroyService Management Services Pte Ltd\n2. Golden Steppe LLP\n3. Service Pipes Holdings LLP\n4. KazStroy Investment and Advisory Pvt Ltd\n5. Nostrum Services N.V.\n6. Nostrum Oil & Gas UK Limited\n7. Amersham Oil LLP\n8. Nostrum E&P Services LLC\n9. Steppe Capital Advisors LLP\n10. Astana KZ National Combined KVN Team Corporate Fund\n11. Express Consulting LLP\n12. Geolix Trans LLP\n13. Standard Petroleum & Co LLP\n14. RTI ANPZ LLP\n15. Forza Securidad S.L.\n16. Polymetal International plc\n17. KazCom TransSystem LLP"}},{"id":"SG-H2534-A900003","no":900003,"noLabel":{"en":"FOURTH SCHEDULE"},"text":{"en":"FOURTH SCHEDULE\nParagraph 6(5)\nUltimate entities\n1. KSS GETR LLP\n2. Diada Capital S.L\n3. Margotrade Investments s.r.o\n4. Infrastructure Developments Central Asia B.V.\n5. Grandstill LLC\n6. Nostrum Associated Investments LLP\n7. Aquila Gold B.V.\n8. Sumeru LLP\n9. Precious Oil Products Investments B.V.\n10. Sumeru Gold B.V.\n11. Gemini Mining Holdings B.V.\n12. Gemini Mining B.V.\n13. KazStroyService Management Services Pte Ltd\n14. Golden Steppe LLP\n15. KazStroy Investment and Advisory Pvt Ltd\n16. Steppe Capital Advisors LLP\n17. Geolix Trans LLP\n18. Standard Petroleum & Co LLP\n19. Forza Securidad S.L."}},{"id":"SG-H2534-A900004","no":900004,"noLabel":{"en":"FIFTH SCHEDULE"},"text":{"en":"FIFTH SCHEDULE\nParagraph 7(5)\nUltimate entities\n1. KSS GETR LLP\n2. Diada Capital S.L\n3. Margotrade Investments s.r.o\n4. Infrastructure Developments Central Asia B.V.\n5. Grandstill LLC\n6. Nostrum Associated Investments LLP\n7. Aquila Gold B.V.\n8. Sumeru LLP\n9. Precious Oil Products Investments B.V.\n10. Sumeru Gold B.V.\n11. Gemini Mining Holdings B.V.\n12. Gemini Mining B.V.\n13. KazStroyService Management Services Pte Ltd\n14. Golden Steppe LLP\n15. KazStroy Investment and Advisory Pvt Ltd\n16. Steppe Capital Advisors LLP\n17. Geolix Trans LLP\n18. Standard Petroleum & Co LLP\n19. Forza Securidad S.L.\n20. Drillco Venture B.V."}}],"pack":"sg-p32","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1749-SG-1200","source":"Income Tax (Steppe Capital Pte Ltd — Section 13(12) Exemption) Order 2022","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2535"] = {"id":"SG-H2535","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S132-2023?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"所得税（信托替代异议期）规则 2023","en":"Income Tax (Substituted Objection Period for Trusts) Rules 2023","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S132-2023","completenessNote":"全文，共 3 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2535-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. These Rules are the Income Tax (Substituted Objection Period for Trusts) Rules 2023 and come into operation on 22 March 2023."}},{"id":"SG-H2535-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Definition"},"text":{"en":"2. In these Rules, “intestate” has the meaning given by section 3 of the Intestate Succession Act 1967."}},{"id":"SG-H2535-A3","no":3,"noLabel":{"en":"3."},"heading":{"en":"Substituted period for objection to notice of assessment"},"text":{"en":"3.—(1) The period in section 76(3)(b) of the Act within which a trustee of a trust may make an application objecting to a notice of assessment of tax on any income of the trust that is dated on or after 22 March 2023, is substituted with the period of 2 months from the date of the service of the notice of assessment.\n(2) Paragraph (1) does not apply to the trustee of a testamentary trust or a trust that arises on the death of an intestate."}}],"pack":"sg-p32","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Substituted Objection Period for Trusts) Rules 2023","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2536"] = {"id":"SG-H2536","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S46-2018?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（飞机包机付款预扣税的替代税率）规则 2018","en":"Income Tax (Substituted Rate for Withholding of Tax for Aircraft Charter Payments) Rules 2018","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S46-2018","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2536-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. These Rules are the Income Tax (Substituted Rate for Withholding of Tax for Aircraft Charter Payments) Rules 2018 and are deemed to have come into operation on 29 December 2016."}},{"id":"SG-H2536-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Substituted rate of withholding tax"},"text":{"en":"2. The rate for the deduction of tax in section 45(1)(a)(iii) of the Act (as applied by section 45A(1) of the Act) is substituted with 2% for a person making a payment, under any agreement or arrangement for the charter of any aircraft, to another person not known to the first person to be resident in Singapore."}}],"pack":"sg-p32","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Substituted Rate for Withholding of Tax for Aircraft Charter Payments) Rules 2018","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2537"] = {"id":"SG-H2537","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S934-2021?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（Sunstar Singapore 私人有限公司依第 13（12）条享有的豁免）命令 2021","en":"Income Tax (Sunstar Singapore Pte. Ltd. — Section 13(12) Exemption) Order 2021","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S934-2021","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2537-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order is the Income Tax (Sunstar Singapore Pte. Ltd. — Section 13(12) Exemption) Order 2021."}},{"id":"SG-H2537-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2.—(1) Income comprising dividends amounting to $18,249,090 that is received in Singapore by Sunstar Singapore Pte. Ltd. (a company incorporated in Singapore) from Sunstar Marketing Hong Kong Ltd (a company incorporated in Hong Kong) in the basis periods for the years of assessment 2017 to 2019 is exempt from tax.\n(2) The exemption in sub-paragraph (1) is subject to the terms and conditions specified in the letter of approval dated 23 July 2021 addressed to Drew & Napier LLC."}}],"pack":"sg-p32","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Sunstar Singapore Pte. Ltd. — Section 13(12) Exemption) Order 2021","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2538"] = {"id":"SG-H2538","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S535-2021?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（Suntec 房地产投资信托——第 13(12) 条豁免）命令 2021","en":"Income Tax (Suntec Real Estate Investment Trust — Section 13(12) Exemption) Order 2021","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S535-2021","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2538-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order is the Income Tax (Suntec Real Estate Investment Trust — Section 13(12) Exemption) Order 2021."}},{"id":"SG-H2538-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2.—(1) Trust distribution income described in sub‑paragraph (2), that is received in Singapore on or after 18 June 2021 by the trustee of Suntec Real Estate Investment Trust or Suntec REIT UK 1 Pte. Ltd. (a Singapore‑incorporated company), from Victoria Circle Unit Trust 1 (a Jersey property unit trust) or Victoria Circle Unit Trust 2 (a Jersey property unit trust), is exempt from tax.\n(2) Sub‑paragraph (1) applies to the following income:\n(a)any rental or other property‑related income derived from a specified property;\n(b)any gain from the disposal of a specified property;\n(c)any gain from the disposal of any partnership interest in any of the following partnerships registered or formed in the United Kingdom:\n(i)Nova Limited Partnership;\n(ii)Nova Residential Limited Partnership.\n(3) The exemption in sub‑paragraph (1) is subject to the conditions specified in the letter of approval dated 18 June 2021 addressed to Ernst & Young Solutions LLP.\n(4) In this paragraph, “specified property” means any of the following properties situated in the United Kingdom:\n(a)Nova North;\n(b)Nova South;\n(c)The Nova Building."}}],"pack":"sg-p32","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Suntec Real Estate Investment Trust — Section 13(12) Exemption) Order 2021","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2539"] = {"id":"SG-H2539","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S30-2003?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":25,"structureMode":"ARTICLE","title":{"zh":"所得税（补充退休计划）条例 2003","en":"Income Tax (Supplementary Retirement Scheme) Regulations 2003","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S30-2003","completenessNote":"全文，共 25 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2539-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1.—(1) These Regulations may be cited as the Income Tax (Supplementary Retirement Scheme) Regulations 2003.\n(2) These Regulations shall, with the exception of regulation 9(3) to (6), come into operation on 13th January 2003.\n(3) Regulation 9(3) to (6) shall be deemed to have come into operation on 1st April 2001."}},{"id":"SG-H2539-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Definitions"},"text":{"en":"2.—(1) In these Regulations —\n[Deleted by S 231/2005 wef 01/01/2005]\n“deposit” has the meaning given to that word in section 4B of the Banking Act (Cap. 19);\n[S 521/2010 wef 15/09/2010]\n“financial institution” means any institution licensed or approved by, or registered with or otherwise regulated by, the Monetary Authority of Singapore under any written law;\n[S 521/2010 wef 15/09/2010]\n“financial product provider” means any financial institution which accepts or has accepted deposits, or offers or has offered gold certificates or investment products, under the SRS;\n[S 521/2010 wef 15/09/2010]\n“investment product” has the meaning given to that expression in the Financial Advisers Act (Cap. 110);\n[S 521/2010 wef 15/09/2010]\n“year” means any year from 1st January to 31st December.\n[S 231/2005 wef 01/01/2005]\n(2) In these Regulations other than regulation 7(2)(a), unless the context otherwise requires —\n(a)a reference to an SRS member making a contribution to his SRS account includes his employer making a contribution to that account on his behalf;\n(b)a reference to a contribution of, by or from an SRS member to his SRS account includes a contribution by his employer to that account on his behalf.\n[S 521/2010 wef Y/A 2009 & subs Ys/A]\n(3) In these Regulations, a reference to an investment, unless the context otherwise requires, includes a deposit.\n[S 405/2015 wef 01/07/2015]\n(4) In these Regulations —\n(a)a withdrawal from an SRS account;\n(b)a withdrawal of moneys from an SRS account; or\n(c)a withdrawal of SRS funds from an SRS account,\nincludes a deduction of a sum representing an investment from the balance in the SRS account that is approved under regulation 14A.\n[S 405/2015 wef 01/07/2015]"}},{"id":"SG-H2539-A3","no":3,"noLabel":{"en":"3."},"heading":{"en":"Establishment of Supplementary Retirement Scheme"},"text":{"en":"3. As from 1st April 2001, there shall be established a scheme called the Supplementary Retirement Scheme."}},{"id":"SG-H2539-A4","no":4,"noLabel":{"en":"4."},"heading":{"en":"SRS operators"},"text":{"en":"4.—(1) An SRS operator shall —\n(a)exercise due diligence and reasonable care in discharging the duties, obligations and requirements set out in the Act relating to the SRS and these Regulations;\n(b)ensure that its operation of the SRS is audited as part of the annual audit of its business;\n(c)at any time, maintain comprehensive records and documents pertaining to its operation of the SRS —\n(i)for 5 years of assessment, in the case of records and documents pertaining to year of assessment 2008 or any subsequent year of assessment; or\n(ii)for 7 years of assessment, in the case of records and documents pertaining to any year of assessment before the year of assessment 2008;\n[S 521/2010 wef 15/09/2010]\n(d)ensure that the sums standing in an SRS account maintained with the SRS operator are not co-mingled with funds standing in any other account, whether maintained with that SRS operator or any other person;\n(e)provide each of its SRS members with a statement at least once a year showing the opening and closing balances of their SRS accounts and the details of their transactions carried out during the year;\n(f)reflect transactions in an SRS account maintained with the SRS operator in Singapore dollars and for this purpose use the exchange rate prevailing on the date of a foreign currency transaction in reflecting that transaction in its Singapore dollar equivalent; and\n(g)upon receipt of information of the death of an SRS member, forward such information to the Comptroller immediately.\n(2) An SRS operator shall furnish to the Comptroller —\n(a)information relating to contributions to and withdrawals from SRS accounts maintained with the SRS operator for each year, in a form and manner acceptable to the Comptroller, by 15th February of the following year or by such other date as may be determined by the Comptroller;\n(b)the names of SRS members having SRS accounts with the SRS operator and the balance remaining in their SRS accounts (excluding any life annuity) that are deemed to be withdrawn under section 10L (6), (7) or (9) of the Act for each year, in a form and manner acceptable to the Comptroller, by 15th February of the following year or by such other date as may be determined by the Comptroller; and\n(c)such other information and documents relating to the operation of the SRS by the SRS operator as may be required by the Comptroller.\n(2A) For the purposes of paragraph (2), information concerning the valuation of any investment that is deducted from the balance in an SRS account must be calculated in accordance with regulation 14B.\n[S 405/2015 wef 01/07/2015]\n(3) An SRS operator shall furnish to the Minister at such time as the Minister may require —\n(a)information on —\n(i)the size of the SRS funds under its administration;\n(ii)the size of investments, including deposits, in such asset classes as may be required by the Minister; and\n[S 521/2010 wef 15/09/2010]\n[S 405/2015 wef 01/07/2015]\n(iii)the total number of SRS accounts maintained with the SRS operator; and\n(b)such other information and documents relating to its operation of the SRS as may be required by the Minister.\n(4) An SRS operator who fails to comply with paragraph (1), (2) or (3) shall be guilty of an offence.\n(5) Where an SRS operator, in contravention of any provision of the Act relating to the SRS or these Regulations —\n(a)fails, without reasonable excuse, to deduct any amount of tax or penalty which it is required to deduct; or\n(b)makes any wrongful or unauthorised payment under the SRS,\nthe SRS operator shall pay to the Comptroller any tax undercharged or the penalty, as the case may be."}},{"id":"SG-H2539-A5","no":5,"noLabel":{"en":"5."},"heading":{"en":"Termination of appointment of SRS operator"},"text":{"en":"5.—(1) The appointment of an SRS operator may be terminated as follows:\n(a)the Minister may, at any time, by notice in writing to an SRS operator, revoke the appointment of the SRS operator; or\n(b)an SRS operator may, at any time, by notice in writing to the Minister, relinquish its appointment as an SRS operator.\n(2) Prior to the termination of its appointment, an SRS operator shall —\n(a)inform all its SRS members that its appointment as an SRS operator is being terminated and that it will transfer their SRS accounts to any other SRS operator of their choice;\n(b)complete the transfer of SRS accounts maintained with it within 6 months from the date of the notice referred to in paragraph (1)(a) or (b), or such other period as the Minister may allow;\n(c)continue to discharge its duties and obligations under the Act and these Regulations until all SRS accounts maintained with it have been transferred to other SRS operators; and\n(d)bear all costs relating to the transfer of its SRS accounts to other SRS operators.\n(3) Where an SRS member fails to choose another SRS operator to take the place of his SRS operator whose appointment is being terminated such that his SRS operator is unable to comply with its obligation under paragraph (2)(b), the SRS operator whose appointment is being terminated shall transfer the SRS account of that SRS member to such other SRS operator as the Minister may direct.\n(4) The appointment of an SRS operator shall terminate upon completion of the transfer of all SRS accounts maintained with it in accordance with paragraph (2)(b)."}},{"id":"SG-H2539-A6","no":6,"noLabel":{"en":"6."},"heading":{"en":"SRS members and SRS accounts"},"text":{"en":"6.—(1) No person may be an SRS member unless he is an individual who —\n(a)has attained the age of 18 years;\n[S 521/2010 wef 01/02/2011]\n(b)is not an undischarged bankrupt; and\n(c)is not mentally disordered and is capable of managing himself and his affairs.\n[S 521/2010 wef 01/03/2010]\n(2) Subject to paragraph (3), any person who wishes to be an SRS member may apply to an SRS operator for an SRS account to be opened and his application shall be accompanied by —\n(a)his consent for the SRS operator to release to the Comptroller or Minister the information specified in regulation 4(2) and (3); and\n(b)such information or documents relevant to the opening of the SRS account as the SRS operator may require.\n[S 521/2010 wef 01/02/2011]\n(3) Subject to paragraph (6), an SRS member shall not apply to an SRS operator to open an SRS account if —\n(a)he already has an SRS account (including one that has been suspended) with the same or another SRS operator;\n(b)he has a pending application with another SRS operator to open an SRS account; or\n(c)he previously had an SRS account with the same or another SRS operator and all the moneys in the account had been withdrawn —\n(i)on the ground that he is physically or mentally incapacitated from ever continuing in any employment, is either (if withdrawal is made before 1st March 2010) found to be of unsound mind or (if withdrawal is made on or after that date) mentally disordered and incapable of managing himself or his affairs, or is suffering from a terminal illness or disease; or\n(ii)on or after reaching the prescribed retirement age prevailing at the time of his first contribution.\n[S 521/2010 wef 01/02/2011]\n(4) An SRS member who contravenes paragraph (3) shall be guilty of an offence.\n(5) Subject to paragraphs (5A) and (5B), where an applicant qualifies under paragraph (1) to be an SRS member, the SRS operator shall open an SRS account for that applicant, but only after —\n(a)obtaining a declaration from the applicant that —\n(i)he has no other SRS account (including one that has been suspended) at the time of application or, if he has an SRS account with another SRS operator, he has already taken all the necessary steps to close that account;\n(ii)he does not have a pending application with another SRS operator to open an SRS account at that time; and\n(iii)he did not previously have an SRS account all the moneys in which were withdrawn on the ground referred to in paragraph (3)(c)(i), or on or after reaching the age referred to in paragraph (3)(c)(ii); and\n(b)informing the applicant of the conditions of the SRS, including the following:\n(i)that an SRS member cannot have an SRS account with more than one SRS operator, a suspended SRS account being treated as an SRS account;\n(ii)the obligations of an SRS member under regulation 11(1);\n(iii)that the maximum amount of deduction under section 39(2)(o) of the Act is subject to the SRS contribution cap applicable to that SRS member;\n(iv)that SRS withdrawals are chargeable to tax in accordance with section 10L of the Act, and the circumstances in which a 5% penalty will be imposed under the Act on withdrawals;\n(v)that an SRS member cannot contribute to his SRS account if he had previously made a withdrawal from this or a previous SRS account of his on the ground referred to in paragraph (3)(c)(i), or on or after reaching the age referred to in paragraph (3)(c)(ii); and\n(vi)that an SRS member is subject to Part XX of the Act if he contravenes any provision of the Act relating to the SRS and regulation 20 if he contravenes these Regulations.\n[S 521/2010 wef 01/02/2011]\n(5A) A declaration in respect of the matter referred to in paragraph (5)(a)(iii) need not be obtained if the applicant informs the SRS operator that the SRS account is to take the place of an existing SRS account with another SRS operator.\n[S 521/2010 wef 01/02/2011]\n(5B) An SRS operator shall not open an SRS account for an applicant if —\n(a)the applicant already has an SRS account with the SRS operator, including one that has been suspended;\n(b)the applicant previously had an SRS account with the SRS operator and made a withdrawal from that account on the ground referred to in paragraph (3)(c)(i), or on or after reaching the age referred to in paragraph (3)(c)(ii), unless the SRS account to be opened is to replace an existing SRS account opened with another SRS operator; or\n(c)he knows or has reason to believe that any part of the declaration referred to in paragraph (5)(a) is false in a material particular.\n[S 521/2010 wef 01/02/2011]\n(5C) An SRS operator shall not be taken to have contravened regulation (5B)(b) if, without being in contravention of regulation 4(1)(c), it has no record or document evidencing such withdrawal.\n[S 521/2010 wef 01/02/2011]\n(6) Where an SRS member who has an existing SRS account informs the SRS operator that he wishes to open an SRS account with another SRS operator in place of the existing SRS account, the SRS operator with whom the existing SRS account of that SRS member is maintained shall —\n(a)transfer the sum standing in the SRS account of that SRS member to the SRS operator specified by the SRS member; and\n(b)upon such transfer, close the existing SRS account of that SRS member and hand over to the other SRS operator sufficient records and documents pertaining to that SRS account to enable the other SRS operator to operate the new SRS account of the SRS member.\n[S 521/2010 wef 01/02/2011]\n(7) An SRS operator who —\n(a)opens an SRS account without obtaining the consent of an applicant referred to in paragraph (2)(a); or\n(b)fails to comply with paragraph (5)(a), (5B) or (6),\nshall be guilty of an offence.\n[S 521/2010 wef 01/02/2011]"}},{"id":"SG-H2539-A7","no":7,"noLabel":{"en":"7."},"heading":{"en":"Suspension of SRS accounts"},"text":{"en":"7.—(1) The Comptroller may direct an SRS operator to suspend an SRS account maintained with that SRS operator if the SRS member of that account contravenes any provision of the Act relating to the SRS or these Regulations.\n(2) Where an SRS account of an SRS member is suspended under paragraph (1), the SRS member —\n(a)shall not make any further contribution to his SRS account;\n(aa)shall, if he had instructed or authorised his employer to make any contribution on his behalf to his SRS account, immediately revoke such instruction or authorisation in writing;\n[S 521/2010 wef 15/09/2010]\n(b)shall not use his SRS funds to acquire any investment, including the making of a deposit;\n[S 521/2010 wef 15/09/2010]\n[S 405/2015 wef 01/07/2015]\n(c)shall return to his SRS account —\n(i)all gains or profits arising from any investment (other than a deposit) acquired using his SRS funds during the period of suspension; and\n[S 405/2015 wef 01/07/2015]\n(ii)all proceeds from the disposal of such investments during the period of suspension;\n(ca)shall return to his SRS account all deposits made using SRS funds during the period of suspension, together with all gains and interest derived from such deposits; and\n[S 521/2010 wef 15/09/2010]\n(d)shall only be allowed to make such withdrawals from his SRS account as the Comptroller may direct.\n(3) An SRS member who contravenes paragraph (2) shall be guilty of an offence.\n(3A) Where an SRS account of an SRS member is suspended under paragraph (1), the SRS operator shall not accept any contribution to his SRS account or allow the SRS funds to be used in contravention of paragraph (2)(b).\n[S 521/2010 wef 15/09/2010]\n(3B) An SRS operator who contravenes paragraph (3A) shall be guilty of an offence.\n[S 521/2010 wef 15/09/2010]\n(4) Notwithstanding the suspension of an SRS account, the SRS operator may deduct from the SRS account any fees and charges in relation to the operation of the SRS account.\n(5) The suspension of an SRS account shall remain in effect for such period and shall be subject to such terms and conditions as the Comptroller may specify."}},{"id":"SG-H2539-A8","no":8,"noLabel":{"en":"8."},"heading":{"en":"Contributions to SRS accounts"},"text":{"en":"8.—(1) All contributions to an SRS account shall be made in the form of cash.\n[S 521/2010 wef 15/09/2010]\n(2) [Deleted by S 521/2010 wef 15/09/2010]\n(3) [Deleted by S 521/2010 wef 15/09/2010]\n(4) An SRS member may make contributions in a year to his SRS account if and only if he derives income in that year.\n[S 521/2010 wef 01/10/2008]\n[S 521/2010 wef 01/01/2009]\n(4A) Subject to paragraph (4), an SRS member who has been adjudged a bankrupt and who has made a withdrawal from his SRS account during his bankruptcy may make further contributions to his SRS account upon his discharge from bankruptcy.\n[S 231/2005 wef 01/01/2005]\n[S 521/2010 wef 01/10/2008]\n(5) Notwithstanding paragraphs (4) and (4A), an SRS member shall not make any contribution to his SRS account if he had at any time made a withdrawal from his SRS account or a previous SRS account of his —\n(a)on the ground that he —\n(i)was physically or mentally incapacitated from ever continuing in any employment;\n(ii)was either (in the case of a withdrawal before 1st March 2010) found to be of unsound mind or (in the case of a withdrawal on or after that date) mentally disordered and incapable of managing himself or his affairs; or\n(iii)was suffering from a terminal illness or disease; or\n(b)on or after reaching the prescribed retirement age prevailing at the time of his first contribution.\n[S 521/2010 wef 01/10/2008]\n(6) The employer of an SRS member shall not make any contribution to the SRS account of the SRS member on behalf of the SRS member unless —\n(a)the SRS member has instructed or authorised the employer in writing to make that contribution on his behalf, and such instruction or authorisation has not been revoked; and\n(b)the contribution consists solely of the SRS member’s gains or profits from any employment with that employer.\n[S 521/2010 wef 15/09/2010]\n(7) Any person who contravenes paragraph (6) shall be guilty of an offence.\n[S 521/2010 wef 15/09/2010]\n(8) An SRS member shall not make any contribution to his SRS account —\n(a)if the SRS contribution cap applicable to him is nil under regulation 9(1)(a); or\n(b)in any other case, to the extent that it exceeds the SRS contribution cap applicable to the SRS member for that year.\n[S 521/2010 wef 15/09/2010]\n(9) An SRS operator —\n(a)shall accept contributions of an SRS member in any year only after the SRS contribution cap applicable to the SRS member for that year has been computed, and shall credit such contributions into the SRS account of the SRS member;\n(b)shall not accept any contribution from an SRS member in any year to the extent that it exceeds the contribution cap applicable to the SRS member for that year as computed by the SRS operator under regulation 9(3) to (10) (whichever is applicable); and\n(c)shall not accept any contribution from an SRS member if it knows or ought to know that the SRS contribution cap applicable to him is nil under regulation 9(1)(a).\n[S 521/2010 wef 15/09/2010]\n(9A) An SRS operator who contravenes paragraph (9)(a), (b) or (c) shall be guilty of an offence.\n[S 209/2011 wef 21/04/2011]\n(10) For the purposes of paragraphs (8)(b) and (9)(b), a contribution to an SRS account in any year exceeds the contribution cap applicable to an SRS member for that year if that contribution, when added to the contributions already made that year, if any, after deducting the withdrawals from his SRS account already made that year, if any, exceeds the contribution cap.\n[S 521/2010 wef 15/09/2010]\n(11) In this regulation, “gains or profits from any employment” has the meaning given to that expression in section 10(2) of the Act.\n[S 521/2010 wef 15/09/2010]"}},{"id":"SG-H2539-A9","no":9,"noLabel":{"en":"9."},"heading":{"en":"SRS contribution cap"},"text":{"en":"9.—(1) Subject to regulation 10, the contribution cap of an SRS member for any year —\n(a)shall be nil if he had at any time made a withdrawal from his SRS account, including any previous SRS account of his —\n(i)on the ground that he was physically or mentally incapacitated from ever continuing in any employment, was either (in the case of a withdrawal before 1st March 2010) found to be of unsound mind or (in the case of a withdrawal on or after that date) mentally disordered and incapable of managing himself or his affairs, or was suffering from a terminal illness or disease; or\n(ii)on or after reaching the prescribed retirement age prevailing at the time of his first contribution;\n(b)in any other case, shall be computed in accordance with paragraphs (3) to (10), and shall be calculated by the SRS operator of the SRS member.\n[S 231/2005 wef 01/01/2005]\n[S 521/2010 wef 15/09/2010]\n(2) [Deleted by S 231/2005 wef 01/01/2005]\n(3) For the purpose of paragraph (1)(b), the contribution cap of an SRS member shall be computed using the relevant SRS contribution rate multiplied by the relevant income base of the SRS member.\n[S 521/2010 wef 15/09/2010]\n(4) For the purpose of paragraph (3), the relevant SRS contribution rate shall be as follows:\n(a)15% for an SRS member who is a citizen of Singapore or a Singapore permanent resident; and\n(b)35% for an SRS member who is not a citizen of Singapore or a Singapore permanent resident.\n(5) For the purpose of paragraph (3), the relevant income base shall be $102,000.\n[S 231/2005 wef 01/01/2005]\n[S 874/2005 wef 01/01/2006]\n[S 209/2011 wef 01/01/2011]\n[S 762/2015 wef 01/01/2016]\n(6) An SRS operator shall not compute the contribution cap for an SRS member using the contribution rate specified in paragraph (4)(b) unless the SRS member submits a declaration stating that he is not a citizen of Singapore or a Singapore permanent resident.\n[S 231/2005 wef 01/01/2005]\n(7) Every SRS member shall submit such documents as may be required by the SRS operator for the purpose of computing his SRS contribution cap.\n[S 231/2005 wef 01/01/2005]\n(8) The Minister or such person as he may appoint may, upon application by the settlor or trustee of a pension or provident fund —\n(a)approved under section 5 of the Act (other than the Central Provident Fund or any pension or provident fund designated by the Minister under section 39(8) of the Act);\n(b)established at any time before 1st October 2008; and\n(c)which is to be dissolved,\ndesignate the fund as a qualifying fund for the purposes of paragraph (9), subject to such terms and conditions as he may impose.\n[S 231/2005 wef 01/01/2005]\n[S 521/2010 wef 01/10/2008]\n(9) The contribution cap of an SRS member who —\n(a)is a member of a qualifying fund that is dissolved on or after 1st October 2008;\n(b)is entitled in any year to receive a sum of money from that qualifying fund by reason of its dissolution; and\n(c)in that year (or such other year as the Minister or such person as he may appoint may in exceptional circumstances approve) makes a contribution to his SRS account using that sum of money or any part of it,\nshall be increased by the amount referred to in paragraph (10) in the year such contribution is made.\n[S 231/2005 wef 01/01/2005]\n[S 521/2010 wef 01/10/2008]\n(10) The amount referred to in paragraph (9) is the lower of the amounts derived from the following:\n(a)(A x B x C) – D; or\n(b)E,\nwhere A is the relevant income base referred to in paragraph (5);\nB is —\n(i) 15% where the SRS member is a citizen of Singapore or a Singapore permanent resident on the date he makes the contribution referred to in paragraph (9)(c); or\n(ii) 35% in any other case;\nC is the number of years (a part of a year being treated as a full year) between 2001 and the year immediately preceding the year referred to in paragraph (9)(b) (both years inclusive);\nD is the aggregate amount of SRS contributions made by the SRS member in all the years (including a part of a year) immediately preceding the year referred to in paragraph (9)(b); and\nE is the sum of money which the SRS member is entitled to receive from the qualifying fund by reason of the dissolution of the fund,\nexcept that the amount computed in accordance with sub-paragraph (a) shall be treated as nil if D exceeds the product of A, B and C.\n[S 231/2005 wef 01/01/2005]\n[S 521/2010 wef 01/10/2008]\n(11) [Deleted by S 231/2005 wef 01/01/2005]\n(12) [Deleted by S 231/2005 wef 01/01/2005]"}},{"id":"SG-H2539-A10","no":10,"noLabel":{"en":"10."},"heading":{"en":"Effect on contribution cap upon SRS member becoming or ceasing to be citizen of Singapore or Singapore permanent resident"},"text":{"en":"10.—(1) Where —\n(a)an SRS member ceases to be a citizen of Singapore or a Singapore permanent resident in the year in which he has made contributions to his SRS account; and\n(b)he makes a request in that year to his SRS operator to re-compute his SRS contribution cap for that year,\nthe SRS operator shall re-compute the contribution cap in accordance with regulation 9 on a pro-rata basis, taking into account the number of days the SRS member was, and was not, a citizen of Singapore or a Singapore permanent resident in that year.\n(2) Where —\n(a)an SRS member becomes a citizen of Singapore or a Singapore permanent resident in any year; and\n(b)in that year informs his SRS operator that he has become a citizen of Singapore or a Singapore permanent resident,\nthe SRS operator shall re-compute the contribution cap in accordance with regulation 9 on a pro-rata basis, taking into account the number of days the SRS member was, and was not, a citizen of Singapore or a Singapore permanent resident in that year, and shall refund to him any difference between his contribution made in that year and the re-computed contribution cap.\n(3) Where —\n(a)an SRS member becomes a citizen of Singapore or a Singapore permanent resident in any year; and\n(b)in the following year informs his SRS operator that he —\n(i)has become a citizen of Singapore or a Singapore permanent resident; and\n(ii)intends to make, or to instruct or authorise his employer to make on his behalf, contributions to his SRS account in that following year,\n[S 521/2010 wef 15/09/2010]\nthe SRS operator shall at his request re-compute his SRS contribution cap for the year in which he becomes a citizen of Singapore or a Singapore permanent resident in accordance with regulation 9 on a pro-rata basis, taking into account the number of days he was, and was not, a citizen of Singapore or a Singapore permanent resident in that year.\n(4) Where the contributions by an SRS member referred to in paragraph (3) to his SRS account in the year he becomes a citizen of Singapore or a Singapore permanent resident exceeds the re-computed SRS contribution cap, the difference shall be used to reduce the contribution cap for the following year.\n(5) Where the contributions by an SRS member referred to in paragraph (3) to his SRS account in the year he becomes a citizen of Singapore or a Singapore permanent resident exceeds the total of the re-computed contribution cap for that year and the contribution cap for the following year, the difference between the amount contributed and the total of the 2 contribution caps shall be refunded by the SRS operator to the SRS member without penalty.\n(6) Where a refund is made by an SRS operator under paragraph (5), the SRS operator shall comply with section 45E of the Act unless at the time of the refund the SRS member is a citizen of Singapore.\n(7) Notwithstanding any re-computation under paragraph (3), the SRS contribution cap for purposes of section 39(2)(o) of the Act in relation to the year in which the SRS member becomes a citizen of Singapore or a Singapore permanent resident shall be the contribution cap computed as if he had not become a citizen of Singapore or a Singapore permanent resident in that year."}},{"id":"SG-H2539-A11","no":11,"noLabel":{"en":"11."},"heading":{"en":"Use and investment of SRS funds"},"text":{"en":"11.—(1) An SRS member shall not —\n(a)use his SRS funds as collateral, security or guarantee for any financial transaction;\n(b)use any investment (other than a deposit) acquired using his SRS funds as collateral, security or guarantee for any financial transaction, or assign such investment to another person;\n[S 521/2010 wef 15/09/2010]\n[S 405/2015 wef 01/07/2015]\n(c)if he has made a deposit using SRS funds, use as collateral, security or guarantee for any financial transaction, or assign to another person —\n(i)the full amount in the account in which the funds are deposited; or\n(ii)any amount in the account if the amount in the account after deducting the first-mentioned amount is less than the sum of the SRS funds and all gains and interest derived therefrom, less any amount that has been transferred to the member’s SRS account; or\n[S 521/2010 wef 15/09/2010]\n(d)make a nomination under section 49L(2) of the Insurance Act (Cap. 142) in respect of any life insurance product acquired using his SRS funds.\n[S 521/2010 wef 15/09/2010]\n(1A) An SRS member shall not enter into any arrangement with any person with respect to the use of his SRS funds the purpose or one of the purposes of which is to reduce or avoid any liability imposed or which would otherwise have been imposed by or under section 10L of the Act or any provision of these Regulations.\n[S 521/2010 wef 15/09/2010]\n(2) An SRS member who contravenes paragraph (1) or (1A) shall be guilty of an offence.\n[S 521/2010 wef 15/09/2010]\n(3) Subject to paragraph (4), an SRS member may use his SRS funds to make a deposit with a financial institution, or use his SRS funds to acquire only the following investments:\n(a)gold certificates offered by a financial institution;\n(b)any investment product within the meaning of the Financial Advisers Act (Cap. 110) that is offered by or through a financial institution.\n[S 521/2010 wef 15/09/2010]\n(4) Where an investment product is an insurance product, an SRS member shall not use his SRS funds to acquire such insurance product unless —\n(a)it is a single premium insurance product; or\n(b)it provides life insurance coverage (including total and permanent disability benefits) not exceeding 3 times the single premium,\nand the SRS member shall not in any event use his SRS funds to acquire any life insurance product providing for critical illness, health or long term care.\n[S 521/2010 wef 15/09/2010]\n(5) An SRS operator shall —\n(a)ensure that the SRS funds of its SRS members are used only in the manner permitted by paragraph (3);\n(b)ensure that the amount standing to an account in which a deposit has been made using SRS funds of an SRS member does not at any time fall below the sum of the SRS funds deposited and all gains and interest derived therefrom, less any amount that has been transferred to the member’s SRS account;\n(c) ensure that on the closure of an account in which a deposit has been made using SRS funds of an SRS member, a sum comprising the amount of the SRS funds deposited and all gains and interest derived therefrom, less any amount that has been transferred to the member’s SRS account, is transferred to the member’s SRS account;\n(d) ensure that, on the instruction of an SRS member who has made a deposit of SRS funds to transfer from the account in which the SRS funds are deposited to his SRS account a sum comprising not more than the amount of the SRS funds deposited and all gains and interest derived therefrom (less any amount that has been transferred to his SRS account), the sum is so transferred;\n(e)subject to regulation 12(4), ensure that all gains or profits derived from investments (other than any deposit) acquired using SRS funds of any of its SRS members, and all proceeds of sale of such investments, are returned to his SRS account;\n[S 405/2015 wef 01/07/2015]\n(f)not discriminate against any deposit with any financial institution or any investment referred to in paragraph (3) created or distributed by any financial institution;\n(g)endeavour to offer settlement facilities to SRS members for as wide a range of investments referred to in paragraph (3)(a) and (b) as possible;\n[S 405/2015 wef 01/07/2015]\n(h)settle each investment transaction (other than a transaction on a deposit) individually and not allow contra trades or contra settlement; and\n[S 405/2015 wef 01/07/2015]\n(i)upon the death or bankruptcy of any of its SRS members, complete the settlement of any transaction initiated by that SRS member before such death or bankruptcy in accordance with the relevant law.\n[S 521/2010 wef 15/09/2010]\n(6) An SRS operator who contravenes paragraph (5) shall be guilty of an offence.\n(7) Nothing in this regulation shall be taken to require an SRS member to sell any investment product which he acquired using his SRS funds under paragraph (3) in the event that the product ceases to be an investment product within the meaning of the Financial Advisers Act (Cap. 110).\n[S 521/2010 wef 15/09/2010]\n(8) Paragraphs (1) and (5) do not apply to an investment if a sum representing the investment has been deducted from the balance in an SRS account pursuant to an approval under regulation 14A.\n[S 405/2015 wef 01/07/2015]"}},{"id":"SG-H2539-A12","no":12,"noLabel":{"en":"12."},"heading":{"en":"Financial product providers"},"text":{"en":"12.—(1) A financial product provider shall —\n(a)provide such information to an SRS operator as may be necessary to enable the SRS operator to fulfil its duties and obligations under the SRS;\n(b)ensure that the amount standing to an account with the provider in which a deposit has been made using SRS funds of an SRS member does not at any time fall below the sum of the SRS funds deposited and all gains and interest derived therefrom, less any amount that has been transferred to the member’s SRS account;\n[S 521/2010 wef 15/09/2010]\n(c) ensure that on the closure of an account with the provider in which a deposit has been made using SRS funds of an SRS member, a sum comprising the amount of the SRS funds deposited and all gains and interest derived therefrom, less any amount that has been transferred to the member’s SRS account, is transferred to the member’s SRS account;\n[S 521/2010 wef 15/09/2010]\n(d) ensure that on the instruction of an SRS member who has made a deposit of SRS funds to transfer from the account in which the SRS funds are deposited to his SRS account a sum comprising not more than the amount of the SRS funds deposited and all gains and interest derived therefrom (less any amount that has been transferred to his SRS account), the sum is so transferred; and\n[S 521/2010 wef 15/09/2010]\n(e)subject to paragraph (4), ensure that all gains or profits derived from any investment (other than a deposit) acquired from the provider using the SRS funds of an SRS member, and all proceeds of sale of such investment are returned to the SRS account of the member.\n[S 521/2010 wef 15/09/2010]\n[S 405/2015 wef 01/07/2015]\n(1A) A financial product provider shall not enter into any arrangement with an SRS member with respect to the use of that SRS member’s SRS funds the purpose or one of the purposes of which is to reduce or avoid any liability imposed or which would otherwise have been imposed by or under section 10L of the Act or any provision of these Regulations.\n[S 521/2010 wef 15/09/2010]\n(2) Where a financial product provider has contravened any provision of these Regulations, the Minister may, in his discretion, prohibit the financial product provider from participating in the SRS.\n(3) Upon the occurrence of the events stated under section 10L(8) of the Act, a financial product provider that is an insurance company —\n(a)shall comply with regulation 4(1)(a) to (d), (2) and (3) as if it were an SRS operator in respect of annuity payments made by the financial product provider to an SRS member under a life insurance policy; and\n[S 521/2010 wef 15/09/2010]\n(b)shall be liable under those regulations in the same way as if the financial product provider were an SRS operator.\n(4) Upon receipt of information of the death of an SRS member who made any deposit with it using his SRS funds or who acquired any other investment from it using his SRS funds, the financial product provider shall —\n(a)forward such information to the Comptroller or the SRS operator of that SRS member immediately;\n(b)make payment under any insurance policy acquired using the SRS funds of such SRS member in accordance with the relevant law;\n(c)in making payment to beneficiaries under any insurance policy taken up by any deceased SRS member who is not a citizen of Singapore, account to the Comptroller for the withholding tax imposed under section 45E of the Act, and be subject to all the requirements relating to such withholding tax; and\n(d)if the death of the SRS member occurred after the end of the period stipulated under section 10L(5) of the Act, furnish information relating to the payments referred to under sub-paragraphs (b) and (c) in a form and manner acceptable to the Comptroller, by 15th February of the year following the year of payment or by such other date as the Comptroller may allow.\n[S 521/2010, wef Y/A 2009 & Sub. Ys/A]\n[S 521/2010 wef 15/09/2010]\n[S 405/2015 wef 01/07/2015]\n(5) For the purpose of paragraphs (3) and (4), where a financial product provider which is an insurance company, in contravention of any provision of the Act relating to the SRS or these Regulations —\n(a)fails, without reasonable excuse, to deduct any amount of tax or penalty which it is required to deduct; or\n(b)makes any wrongful or unauthorised payments under the SRS,\nthe financial product provider shall pay to the Comptroller the tax undercharged or the penalty, as the case may be.\n(6) A financial product provider who fails to comply with paragraph (1), (1A), (3) or (4) shall be guilty of an offence.\n[S 521/2010 wef 15/09/2010]\n(7) Paragraph (1)(b) to (e) does not apply to an investment if a sum representing the investment has been deducted from the balance in an SRS account pursuant to an approval under regulation 14A.\n[S 405/2015 wef 01/07/2015]"}},{"id":"SG-H2539-A13","no":13,"noLabel":{"en":"13."},"heading":{"en":"Withdrawals from SRS accounts"},"text":{"en":"13.—(1) Subject to regulations 14 and 14A, any withdrawal by an SRS member from his SRS account shall be only in the form of cash, and his SRS operator shall debit such withdrawal from his SRS account.\n[S 405/2015 wef 01/07/2015]\n(2) Where an SRS member has made a withdrawal that is subject to a penalty of 5% under section 10L(2) of the Act, the SRS member shall not be allowed to repay the amount withdrawn into the SRS account whether by himself or another person so as to avoid the penalty.\n[S 521/2010 wef 15/09/2010]\n(3) An application made under section 10L(3)(a) of the Act to withdraw the SRS funds of an SRS member who is not a citizen of Singapore or a Singapore permanent resident at the time of the application shall be accompanied by a declaration that he is not a citizen of Singapore or a Singapore permanent resident.\n(4) An application made under section 10L(3)(a) of the Act to withdraw the SRS funds of an SRS member who is not a citizen of Singapore or a Singapore permanent resident at the time of the application but who was previously a citizen of Singapore or a Singapore permanent resident shall be accompanied by —\n(a)a declaration that he is not a citizen of Singapore or a Singapore permanent resident; and\n(b)a letter from the Immigration and Checkpoints Authority confirming that the SRS member is no longer a citizen of Singapore or a Singapore permanent resident.\n[S 231/2005 wef 01/01/2005]\n(5) An application under section 10L(3)(c) of the Act to withdraw the SRS funds of an SRS member shall be accompanied by a certificate issued by a medical practitioner registered under the Medical Registration Act (Cap. 174) certifying that the SRS member —\n(a)is physically or mentally incapacitated from ever continuing in any employment;\n(b)is mentally disordered and incapable of managing himself or his affairs; or\n[S 521/2010 wef 01/03/2010]\n(c)is suffering from a terminal illness or disease.\n(6) An application to withdraw the SRS funds of an SRS member who is an undischarged bankrupt shall be accompanied by a notice issued by the trustee in bankruptcy of the SRS member or the Official Assignee.\n(7) An SRS operator shall not permit any withdrawal by an SRS member from any SRS account maintained with it to be made under paragraph (5) or (6), unless the Comptroller has approved the withdrawal.\n(8) An SRS operator who contravenes paragraph (7) shall be guilty of an offence."}},{"id":"SG-H2539-A14","no":14,"noLabel":{"en":"14."},"heading":{"en":"Transfer of balance standing in SRS accounts after deemed withdrawals"},"text":{"en":"14.—(1) Where any sum standing in the SRS account of a deceased SRS member is deemed to be withdrawn under section 10L(9) of the Act, the SRS operator shall not transfer such sum out of the SRS account except with the approval of the Comptroller or in accordance with regulation 14A.\n[S 405/2015 wef 01/07/2015]\n(2) [Deleted by S 405/2015 wef 01/07/2015]\n(3) An SRS operator who contravenes paragraph (1) shall be guilty of an offence.\n[S 405/2015 wef 01/07/2015]"}},{"id":"SG-H2539-A14.001","no":14.001,"noLabel":{"en":"14A."},"heading":{"en":"Deduction of investment from balance in SRS account"},"text":{"en":"14A.—(1) An SRS operator may approve an application by an SRS member for a deduction of an investment from the balance in an SRS account in accordance with this regulation.\n(2) Subject to paragraph (3), an SRS member may, in the manner specified by the member’s SRS operator, apply to the SRS operator to approve a deduction of an investment from the balance in the member’s SRS account in the following circumstances:\n(a)where the deduction would amount to a withdrawal referred to in section 10L(3)(a), (b) or (c) of the Act; or\n(b)at any time after any balance remaining in the member’s SRS account is deemed withdrawn under section 10L(6) or (7) of the Act, or the sums standing in the member’s SRS account are deemed withdrawn under section 10L(9) of the Act.\n(3) No application for a deduction of any investment that is a life annuity may be made under paragraph (2)(b).\n(4) The SRS operator must not approve an SRS member’s application made under paragraph (2) if the SRS operator is not satisfied that —\n(a)the sums representing the investment to be deducted from the balance in the SRS account can be separately identified; and\n(b)the investment to be deducted from the balance in the SRS account can be separately valued in accordance with regulation 14B.\n(5) Where the SRS operator approves an SRS member’s application made under paragraph (2), the date of approval is taken to be —\n(a)where the SRS member is a citizen of Singapore, the application receipt date; and\n(b)where the SRS member is not a citizen of Singapore, the date on which the SRS operator has collected tax from the SRS member in accordance with section 45EA of the Act.\n(6) An SRS operator who fails to comply with paragraph (4) shall be guilty of an offence.\n[S 405/2015 wef 01/07/2015]"}},{"id":"SG-H2539-A14.002","no":14.002,"noLabel":{"en":"14B."},"heading":{"en":"Valuation of investment deducted from balance of SRS account"},"text":{"en":"14B.—(1) This regulation states what the value of an investment that is deducted from the balance in an SRS account is for the purposes of sections 10L(1), (2), (3), (3D) and (3E) and 45EA of the Act.\n(2) Where an investment is deducted pursuant to an application under regulation 14A in the circumstances set out in regulation 14A(2)(a), the investment is to be valued as follows:\n(a)in the case of listed shares, warrants, loan stocks and bonds, the closing price of the investment as at the application receipt date;\n(b)in the case of listed shares, warrants, loan stocks and bonds that are suspended, the last traded price of the investment before the application receipt date;\n(c)in the case of unlisted shares, the net asset value of the shares as at the application receipt date;\n(d)in the case of unit trusts, the published price or last available price of the unit trusts as at the application receipt date;\n(e)in the case of fixed deposits with financial institutions maturing after the date of the application receipt date, the principal amount of the fixed deposits;\n(f)in the case of deposits with financial institutions (other than fixed deposits), the principal amount of the deposits plus all interest that has accrued up to the application receipt date;\n(g)in the case of insurance products, the surrender value of the products as at the application receipt date; or\n(h)in the case of any other investment, the market value of the investment on the application receipt date.\n(3) For the purposes of paragraph (2), if the investment is in a foreign currency, the SRS operator must reflect the value of the investment in Singapore dollars using the exchange rate prevailing on the application receipt date.\n(4) Where an investment is deducted pursuant to an application under regulation 14A in the circumstances set out in regulation 14A(2)(b), the investment is to be valued for the purposes of section 45EA of the Act in accordance with regulation 15(2) and (3).\n(5) Despite paragraphs (2) and (3), if the SRS operator is unable to value the investment under paragraphs (2) and (3), the SRS operator must inform the Comptroller who may determine the value of the investment using any other reasonable basis.\n[S 405/2015 wef 01/07/2015]"}},{"id":"SG-H2539-A14.003","no":14.003,"noLabel":{"en":"14C."},"heading":{"en":"Information to be provided by SRS operator following application made under regulation 14A"},"text":{"en":"14C.—(1) If the SRS operator does not approve an application by an SRS member who is a citizen of Singapore for a deduction of an investment from the balance in the member’s SRS account under regulation 14A(2), the SRS operator must inform the SRS member of that fact and the reason why the application was not approved.\n(2) If the SRS operator approves an application by an SRS member who is a citizen of Singapore for a deduction of an investment from the balance in the member’s SRS account under regulation 14A(2), the SRS operator must inform the SRS member of that fact, the date of approval of the application as determined under regulation 14A(5) and —\n(a)where the application was made in the circumstances referred to in regulation 14A(2)(a) —\n(i)the application receipt date; and\n(ii)the value of the investment as determined under regulation 14B(2) and (3), or regulation 14B(5), whichever may be applicable; or\n(b)where the application was made in the circumstances referred to in regulation 14A(2)(b) —\n(i)the date of the deemed withdrawal under section 10L(6), (7) or (9) of the Act, as the case may be; and\n(ii)the value of the investment as determined under regulation 14B(4).\n(3) If the SRS operator does not propose to approve an application by an SRS member who is not a citizen of Singapore for a deduction of an investment from the balance in the member’s SRS account under regulation 14A(2), the SRS operator must inform the SRS member of that fact and the reason why the application will not be approved.\n(4) If the SRS operator proposes to approve an application by an SRS member who is not a citizen of Singapore for a deduction of an investment from the balance in the member’s SRS account under regulation 14A(2), the SRS operator must, before the SRS operator approves the application, inform the SRS member of the following:\n(a)that it proposes to approve the application;\n(b)that the application will only be approved by the SRS operator after the SRS operator has collected tax from the SRS member in accordance with section 45EA of the Act; and\n(c)either —\n(i)where the application was made in the circumstances referred to in regulation 14A(2)(a) —\n(A)the application receipt date; and\n(B)the value of the investment as determined under regulation 14B(2) and (3), or regulation 14B(5), whichever may be applicable; or\n(ii)where the application was made in the circumstances referred to in regulation 14A(2)(b) —\n(A)the date of the deemed withdrawal under section 10L(6), (7) or (9) of the Act, as the case may be; and\n(B)the value of the investment as determined under regulation 14B(4).\n(5) If the SRS operator approves an SRS member’s application for a deduction of an investment under regulation 14A(2), the SRS operator must also provide such information to any financial product provider as may be agreed between them as will enable the financial product provider to exclude the investment for the purpose of complying with regulation 12(1).\n(6) An SRS operator who fails to comply with paragraph (1), (2), (3), (4) or (5) shall be guilty of an offence.\n[S 405/2015 wef 01/07/2015]"}},{"id":"SG-H2539-A14.004","no":14.004,"noLabel":{"en":"14D."},"heading":{"en":"Definitions for regulations 14A, 14B and 14C"},"text":{"en":"14D.—(1) In regulations 14A, 14B and 14C —\n“application receipt date” means the date on which an SRS member’s application under regulation 14A(2) is received by the SRS operator;\n“SRS member” includes, in the case of an SRS member who is deceased, the legal personal representative of the SRS member.\n(2) For the purposes of regulations 14A, 14B and 14C, a reference to a deduction of an investment from the balance in an SRS account is a reference to a deduction of the sums representing that investment from the balance in that account.\n[S 405/2015 wef 01/07/2015]"}},{"id":"SG-H2539-A15","no":15,"noLabel":{"en":"15."},"heading":{"en":"Amount of withdrawal under section 10L (4) of Act or of deemed withdrawal where deposits made or other investments purchased using SRS funds"},"text":{"en":"15.—(1) Where any excess contribution is made by an SRS member to his SRS account and he fails to make any withdrawal required under section 10L (4) and the sum standing in his SRS account includes deposits or other investments or both, the deposits and other investments (as the case may be) as at 31st December of the year in which the SRS member has been notified by the Comptroller of the excess contribution shall be valued as follows:\n(a)in the case of listed shares, warrants, loan stocks and bonds, the closing price of the investment as at that date;\n(b)in the case of listed shares, warrants, loan stocks and bonds that are suspended, the last traded price of the investment before that date;\n(c)in the case of unlisted share, the net asset value of the shares as at that date;\n[S 521/2010 wef 15/09/2010]\n(d)in the case of unit trusts, the published price or last available price as at that date;\n(e)in the case of fixed deposits with financial institutions maturing after that date, the principal amount of the fixed deposits;\n(f)in the case of deposits with financial institutions (other than fixed deposits), the principal amount of the deposit plus all interest accrued up to that date;\n(g)in the case of insurance products, the surrender value as at that date as determined by the insurance companies; and\n(h)in the case of any other investment, the market value of the investment as at that date.\n[S 405/2015 wef 01/07/2015]\n[S 521/2010 wef 15/09/2010]\n(2) Where any balance remaining in the SRS account of an SRS member which is deemed to be withdrawn under section 10L (6), (7) or (9) of the Act includes deposits made or other investments acquired using SRS funds or both, the deposits and other investments (as the case may be) shall be valued as follows:\n(a)in the case of listed shares, warrants, loan stocks and bonds, the closing price of the investment as at the date of the deemed withdrawal;\n(b)in the case of listed shares, warrants, loan stocks and bonds that are suspended, the last traded price of the investment before the date of the deemed withdrawal;\n(c)in the case of unlisted shares, the net asset value of the shares as at the date of the deemed withdrawal;\n[S 521/2010 wef 15/09/2010]\n(d)in the case of unit trusts, the published price or last available price as at the date of the deemed withdrawal;\n(e)in the case of fixed deposits with financial institutions maturing after the deemed withdrawal date, the principal amount of the fixed deposits;\n(f)in the case of deposits with financial institutions (other than fixed deposits), the principal amount of the deposit plus all interest accrued up to the date of the deemed withdrawal;\n(g)in the case of insurance products, the surrender value as at the date of the deemed withdrawal or the actual amount paid out (in the case of death), as determined by the insurance companies; and\n(h)in the case of any other investment, the market value of the investment as at the date of the deemed withdrawal.\n[S 521/2010 wef 15/09/2010]\n[S 405/2015 wef 01/07/2015]\n(3) Where any deposit or other investment referred to in paragraph (1) or (2) is in a foreign currency, the SRS operator shall reflect the value of the deposit or other investment in Singapore dollars using the exchange rate prevailing on the date the value of the deposit or other investment is required to be determined.\n[S 521/2010 wef 15/09/2010]\n[S 405/2015 wef 01/07/2015]\n(4) The SRS operator shall provide the value of deposits or other investments as determined under paragraphs (1), (2) and (3) to the Comptroller.\n[S 521/2010 wef 15/09/2010]\n[S 405/2015 wef 01/07/2015]\n(5) An SRS operator who fails to comply with paragraph (4) shall be guilty of an offence.\n(6) Where the Comptroller is satisfied that it is not possible for an SRS operator to provide the value of any deposit or other investment under paragraphs (1) and (2), the Comptroller may determine the value of such deposit or other investment using any other reasonable basis.\n[S 521/2010 wef 15/09/2010]\n[S 405/2015 wef 01/07/2015]"}},{"id":"SG-H2539-A16","no":16,"noLabel":{"en":"16."},"heading":{"en":"Computation of income deemed to accrue from excess contribution"},"text":{"en":"16. For the purpose of section 10L(4)(a) of the Act, any excess contribution made by an SRS member shall be compounded at 5% yearly from 1st January of the year following the year in which the excess contribution was made by the SRS member, to the last day of the month before the month in which the SRS member was notified by the Comptroller of the excess contribution."}},{"id":"SG-H2539-A17","no":17,"noLabel":{"en":"17."},"heading":{"en":"Fees and charges"},"text":{"en":"17.—(1) SRS operators and financial product providers may impose fees and charges for maintaining an SRS account and for providing any other service to an SRS member relating to the SRS, and all such fees and charges shall be deducted by the SRS operator from the SRS funds of that SRS member.\n(2) An SRS operator shall make available the full schedule of fees and charges that the SRS operator levies.\n(3) An SRS operator shall not deduct any fees and charges in relation to an investment transaction from an SRS account opened with it which will result in a negative cash balance in the SRS account.\n(4) An SRS operator who contravenes paragraph (1) or (3) shall be guilty of an offence."}},{"id":"SG-H2539-A18","no":18,"noLabel":{"en":"18."},"heading":{"en":"Application of Regulations to existing accounts, etc."},"text":{"en":"18. Where, immediately before 13th January 2003, any account was opened by any person with an SRS operator for the purpose of participating in the SRS —\n(a)such account shall be treated as an SRS account opened under these Regulations;\n(b)such person shall be treated as an SRS member under these Regulations;\n(c)any contribution made to an account referred to in paragraph (a) shall be treated as a contribution made to an SRS account under these Regulations;\n(d)any withdrawal from an account referred to in paragraph (a) shall be treated as a withdrawal made from an SRS account under these Regulations;\n(e)any investment acquired using any funds in an account referred to in paragraph (a) shall be treated as an investment acquired using SRS funds under these Regulations; and\n(f)any deduction of fees and charges by an SRS operator from an account referred to in paragraph (a) shall be treated as a deduction of fees and charges by an SRS operator under these Regulations."}},{"id":"SG-H2539-A19","no":19,"noLabel":{"en":"19."},"heading":{"en":"Withdrawal under section 10L(3)(b) of Act disregarded in certain cases"},"text":{"en":"19.—(1) Notwithstanding regulation 8 and (with effect from 15th September 2010) regulation 9(1)(a), where an SRS member —\n(a)made his first withdrawal under section 10L(3)(b) of the Act from his SRS account; and\n(b)subsequently made one or more contributions to his SRS account during the period between 1st October 2008 and 31st December 2008 (both dates inclusive),\nthen any withdrawal made under 10L(3)(b) of the Act prior to the date of the first of his contributions referred to in paragraph (b) shall be disregarded for the purposes of those provisions.\n(2) Notwithstanding regulation 8 and (with effect from 15th September 2010) regulation 9(1)(a), where an SRS member —\n(a)made one or more withdrawals under section 10L(3)(b) of the Act of all the funds standing to his SRS account and closed his SRS account; and\n(b)subsequently opened another SRS account during the period between 1st October 2008 and 31st December 2008 (both dates inclusive),\nthen the withdrawal or withdrawals shall be disregarded for the purposes of those provisions.\n[S 521/2010 wef 01/10/2008]"}},{"id":"SG-H2539-A20","no":20,"noLabel":{"en":"20."},"heading":{"en":"Penalty"},"text":{"en":"20.—(1) Any person who is guilty of an offence under these Regulations (other than regulation 11(1A) or 12(1A)) shall be liable on conviction to a fine not exceeding $1,000 and in default of payment to imprisonment for a term not exceeding 6 months.\n(2) Any person who is guilty of an offence under regulation 11(1A) or 12(1A) shall be liable on conviction to a fine not exceeding $2,000 or to imprisonment for a term not exceeding 12 months or to both.\n[S 521/2010 wef 01/02/2011]"}},{"id":"SG-H2539-A21","no":21,"noLabel":{"en":"21."},"heading":{"en":"Composition of offences"},"text":{"en":"21.—(1) Any offence under these Regulations, other than an offence under regulation 11(1A) or 12(1A), may be compounded by the Comptroller in accordance with section 243 of the Criminal Procedure Code (Cap. 68).\n[S 405/2015 wef 01/07/2015]\n(2) The Comptroller may compound an offence by collecting from the person reasonably suspected of having committed the offence a sum of money not exceeding $500.\n[S 521/2010 wef 01/02/2011]"}}],"pack":"sg-p32","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1749-SG-1200","source":"Income Tax (Supplementary Retirement Scheme) Regulations 2003","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2540"] = {"id":"SG-H2540","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S881-2022?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（SY RORO 4 私人有限公司依第 13（4）条享有的豁免）公告 2022","en":"Income Tax (SY RORO 4 Pte. Ltd. — Section 13(4) Exemption) Notification 2022","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S881-2022","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2540-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. This Notification is the Income Tax (SY RORO 4 Pte. Ltd. — Section 13(4) Exemption) Notification 2022 and is deemed to have come into operation on 30 November 2021."}},{"id":"SG-H2540-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2.—(1) The interest payable by SY RORO 4 Pte. Ltd., a wholly‑owned subsidiary of Seven Yield Pte. Ltd., to Oriental Fleet RORO 01 Limited during the relevant period, under a sale and lease‑back agreement dated 25 November 2021 in respect of the vessel “LIEKUT”, is exempt from tax.\n(2) The exemption under sub-paragraph (1) is subject to the conditions specified in the letter from the Ministry of Finance dated 13 October 2022 and addressed to EY Corporate Advisors Pte. Ltd.\n(3) In this paragraph, “relevant period” means the period starting on 30 November 2021 and ending on the earlier of the following (both dates inclusive):\n(a)29 November 2026;\n(b)the date of withdrawal or revocation of the approval given under section 13P of the Act to Seven Yield Pte. Ltd. as an approved shipping investment enterprise, if the approval is so withdrawn or revoked."}}],"pack":"sg-p32","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (SY RORO 4 Pte. Ltd. — Section 13(4) Exemption) Notification 2022","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2541"] = {"id":"SG-H2541","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S685-2012?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":9,"structureMode":"ARTICLE","title":{"zh":"所得税（合伙企业税收优惠）条例 2012","en":"Income Tax (Tax Incentives for Partnerships) Regulations 2012","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S685-2012","completenessNote":"全文，共 9 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2541-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1.—(1) These Regulations may be cited as the Income Tax (Tax Incentives for Partnerships) Regulations 2012 and shall, with the exception of regulation 4, be deemed to have come into operation on 1st April 2008.\n(2) Regulation 4 shall come into operation on 28th December 2012."}},{"id":"SG-H2541-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Definitions"},"text":{"en":"2.—(1) In these Regulations, unless the context otherwise requires —\n“adjustment factor”, in relation to any year of assessment, means the factor ascertained in accordance with the formula —\nwhere\nA is the applicable concessionary rate of tax under section 43N or 43P (as the case may be); and\nB is the rate of tax specified in section 43(1)(a);\n[S 629/2019 wef 29/12/2016]\n[S 312/2024 wef 31/12/2021]\n[S 312/2024 wef 12/04/2024]\n“approved partnership” means a partnership approved by the Minister or an authorised body under section 13G, 13P, 43N or 43P, as the case may be;\n[S 312/2024 wef 31/12/2021]\n[S 312/2024 wef 12/04/2024]\n“share of divisible income”, in relation to a partner of an approved partnership, means the income of that approved partnership to which that partner is entitled.\n(2) A reference in these Regulations to a section is a reference to a section of the Act.\n(3) A reference in these Regulations to section 13G, 13P, 14E, 19B, 19C, 43N or 43P or any provision thereof is a reference to that section or provision as applied to a partnership under section 36(1A), (1B) or (1C), as the case may be.\n[S 312/2024 wef 31/12/2021]"}},{"id":"SG-H2541-A3","no":3,"noLabel":{"en":"3."},"heading":{"en":"Manner in which concessionary rate of tax may be accorded to individual partner"},"text":{"en":"3. Where a concessionary rate of tax is specified under section 43N or 43P for an approved partnership, the share of the applicable divisible income of a partner of that approved partnership being an individual to be assessed to tax shall be that share of the divisible income (after making the necessary deductions required by the relevant provisions of these Regulations) multiplied by the adjustment factor.\n[S 629/2019 wef 29/12/2016]\n[S 312/2024 wef 31/12/2021]"}},{"id":"SG-H2541-A4","no":4,"noLabel":{"en":"4."},"heading":{"en":"Changes in composition of partnership or approved partnership"},"text":{"en":"4. The precedent partner of —\n(a)a partnership claiming an allowance under section 19B; or\n[S 312/2024 wef 12/04/2024]\n(b)an approved partnership,\nshall give written notice to the Minister or an authorised body for the purpose of these Regulations, of any change in the composition of the partnership or approved partnership, immediately after the change or within such longer period as may be allowed by the Minister or such person as he may appoint.\n[S 312/2024 wef 12/04/2024]"}},{"id":"SG-H2541-A5","no":5,"noLabel":{"en":"5."},"heading":{"en":"Application of section 13G"},"text":{"en":"5.—(1) Section 13G shall apply to the share of divisible income of a partner of an approved partnership derived from making any authorised investment as it applies to the income of an approved venture company derived from making any authorised investment, with the modifications and exceptions set out in this regulation.\n[S 629/2019 wef 29/12/2016]\n[S 312/2024 wef 19/02/2020]\n[S 312/2024 wef 31/12/2021]\n(2) For the purpose of paragraph (1) —\n(a)any reference in section 13G(6) and (7) to an approved venture company is a reference to a partner of an approved partnership;\n[S 629/2019 wef 01/01/2014]\n[S 312/2024 wef 31/12/2021]\n(b)any reference in section 13G(15) to an approved venture company is a reference to an approved partnership; and\n[S 312/2024 wef 31/12/2021]\n(c)paragraphs (3), (4) and (8) apply instead of section 13G(4) and (5).\n[S 629/2019 wef 29/12/2016]\n[S 312/2024 wef 31/12/2021]\n(3) In determining the share of divisible income of a partner of an approved partnership derived from making any authorised investment for any year of assessment (referred to in this paragraph as the “share”) to be exempt from tax under regulations made under section 13G, there shall be deducted therefrom —\n(a)any expenses in respect of such authorised investment of the approved partnership, allowable under the Act for that year of assessment which is apportioned to that share;\n[S 629/2019 wef 17/09/2019]\n[S 312/2024 wef 19/02/2020]\n(b)any loss of the approved partnership for that year of assessment arising from the disposal of any authorised investment in Singapore or elsewhere which is apportioned to that share;\n[S 312/2024 wef 19/02/2020]\n(c)any allowances for that year of assessment under section 19, 19A, 20, 21 or 22 which are apportioned to that share notwithstanding that no claim for the allowance has been made; and\n(d)any balance of the expenses, losses and allowances referred to in sub-paragraphs (a), (b) and (c) which have not been deducted in determining the share of divisible income of the partner from making any authorised investment for any previous year of assessment.\n[S 312/2024 wef 19/02/2020]\n[S 312/2024 wef 31/12/2021]\n(4) Any expenses, allowances or losses referred to in paragraph (3) which are apportioned to the share of divisible income of a partner of an approved partnership derived from making any authorised investment —\n(a)shall only be deducted against the income of the partner that is exempt from tax under regulations made under section 13G; and\n[S 312/2024 wef 31/12/2021]\n(b)shall not be available as a deduction against any other income of the partner, except that any balance of the expenses, allowances or losses remaining unabsorbed at the end of the period specified under section 13G(2A) shall be available as a deduction against any other income of the partner for the year of assessment which relates to the basis period in which the tax exemption ceases and for any subsequent year of assessment in accordance with section 23 or 37, as the case may be.\n[S 629/2019 wef 17/09/2019]\n[S 312/2024 wef 19/02/2020]\n[S 312/2024 wef 31/12/2021]\n(5) [Deleted by S 629/2019 wef 29/12/2016]\n(6) [Deleted by S 629/2019 wef 29/12/2016]\n(7) [Deleted by S 629/2019 wef 29/12/2016]\n(8) In this regulation, “authorised investment” and “venture company” have the meanings given by section 13G.\n[S 312/2024 wef 19/02/2020]\n[S 312/2024 wef 31/12/2021]"}},{"id":"SG-H2541-A6","no":6,"noLabel":{"en":"6."},"heading":{"en":"Application of section 13P"},"text":{"en":"6.—(1) Section 13P applies to the share of divisible income of a partner of an approved partnership derived —\n(a)during the period between 1 April 2008 and 24 March 2016 (both dates inclusive) from the qualifying activities mentioned in paragraphs (a), (b) and (c) of the definition of “qualifying activities” in paragraph (6);\n(b)on or after 1 June 2011 from the qualifying activities mentioned in paragraphs (d), (e) and (f) of the definition of “qualifying activities” in paragraph (6);\n[S 312/2024 wef 12/12/2018]\n(c)on or after 25 March 2016 from the qualifying activities mentioned in paragraphs (g) and (h) of the definition of “qualifying activities” in paragraph (6); and\n[S 312/2024 wef 12/12/2018]\n(d)on or after 12 December 2018 from the qualifying activities mentioned in paragraphs (i) and (j) of the definition of “qualifying activities” in paragraph (6),\nas it applies to the income of an approved shipping investment enterprise from the activities mentioned in section 13P(1)(a), (b), (c), (ca), (cb), (cc), (cd) and (d), with the modifications and exceptions set out in this regulation.\n[S 457/2017 wef 25/03/2016]\n[S 312/2024 wef 12/12/2018]\n[S 312/2024 wef 31/12/2021]\n(2) For the purposes of paragraph (1) —\n(a)a reference in section 13P(2) to a shipping investment enterprise is a reference to a partnership registered under any written law in Singapore;\n[S 312/2024 wef 31/12/2021]\n(b)a reference in section 13P to the approval of a shipping investment enterprise is a reference to the approval of the partnership under section 13P(2);\n[S 312/2024 wef 31/12/2021]\n(c)a reference in section 13P(7), (8) and (18) to an approved shipping investment enterprise is a reference to a partner of the approved partnership;\n[S 457/2017 wef 01/01/2014]\n[S 312/2024 wef 31/12/2021]\n(d)a reference in section 13P(17) to an approved shipping investment enterprise is a reference to the approved partnership;\n[S 312/2024 wef 31/12/2021]\n(e)a reference in section 13P to a sea-going ship acquired, chartered or leased by an approved shipping investment enterprise is a reference to a sea-going ship acquired, chartered or leased by the approved partnership; and\n[S 312/2024 wef 31/12/2021]\n(f)paragraphs (3), (3AA), (3AB), (3AC), (3A), (4), (5) and (5B) apply in lieu of section 13P(1A), (1B), (1C), (1D), (1DA), (1E), (1F), (5), (6) and (6A), and section 13P(1G) is to be construed accordingly.\n[S 457/2017 wef 01/06/2011]\n[S 312/2024 wef 12/12/2018]\n[S 312/2024 wef 07/12/2020]\n[S 312/2024 wef 31/12/2021]\n(3) Section 13P(1) shall continue to apply to —\n(a)a partner of a partnership the approval of which has expired or been withdrawn, but which continues to derive income from qualifying activities in relation to a sea-going ship acquired before or during the period of the approval, provided that the partnership has, or (in a case of income derived from an activity mentioned in paragraph (i) or (j) of the definition of “qualifying activities” in paragraph (6)) both the partnership and the approved related party have, by the date of the expiry or before the withdrawal, fulfilled all the conditions referred to in section 13P(3); and\n[S 312/2024 wef 12/12/2018]\n[S 312/2024 wef 31/12/2021]\n(b)any reference in section 13P and these Regulations to an approved partnership shall be construed accordingly.\n[S 312/2024 wef 12/12/2018]\n[S 312/2024 wef 31/12/2021]\n(3AA) Section 13P(1)(ca) and (cc) does not apply to income derived on or after 12 December 2018 from the chartering or finance leasing of a sea-going ship that is acquired by the approved partnership or the approved related party by way of a finance lease entered into with an entity that was not an approved related party.\n[S 312/2024 wef 12/12/2018]\n[S 312/2024 wef 31/12/2021]\n(3AB) Section 13P(1)(ca) and (cc) also does not apply to any income derived by an approved partnership as part of a business of trading in sea-going ships or constructing sea-going ships for sale.\n[S 312/2024 wef 07/12/2020]\n[S 312/2024 wef 31/12/2021]\n(3AC) Section 13P(1)(cc) and (cd) and (1B) applies (with the necessary modifications) to income derived by a partner of the approved partnership in relation to a ship acquired by a related party of the partnership before the period of approval of the related party, if and only if the approved partnership is approved on or after 1 April 2008.\n[S 312/2024 wef 12/12/2018]\n[S 312/2024 wef 07/12/2020]\n[S 312/2024 wef 31/12/2021]\n(3A) Section 13P(1)(d) does not apply to —\n(a)any income of an approved partnership derived before 12 December 2018 as a lessor of a sea‑going ship under a finance lease that is treated as a sale under section 10C; or\n(b)any income of an approved partnership that is derived as part of a business of trading in sea‑going ships or of constructing sea‑going ships for sale.\n[S 457/2017 wef 01/06/2011]\n[S 312/2024 wef 07/12/2020]\n[S 312/2024 wef 31/12/2021]\n(4) In determining the share of divisible income of a partner of an approved partnership from qualifying activities which is exempt from tax under section 13P(1), the allowance provided for in sections 16, 17, 18, 18B, 18C, 19, 19A, 20, 21, 22 and 23 as apportioned to that share, other than allowances made to a lessee of a sea-going ship under regulations made under section 10C —\n(a)shall be taken into account notwithstanding that no claim for the allowance has been made; and\n(b)shall only be deducted from the share of income of the partner derived from the qualifying activities, and the balance of those allowances shall not be available as a deduction against any other income of the partner; except that any balance remaining unabsorbed at the end of the tax exempt period of the approved partnership shall be available as a deduction against any other income of the partner for the year of assessment which relates to the basis period in which the tax exemption ceases and for any subsequent year of assessment in accordance with section 23.\n[S 312/2024 wef 31/12/2021]\n(5) Where an approved partnership incurs a loss during the tax exempt period of the partnership in respect of qualifying activities, that loss as apportioned to each partner of the partnership —\n(a)shall be deducted against the income of the partner from the qualifying activities in accordance with section 37; and\n(b)shall only be deducted against the income of the partner from the qualifying activities, and the balance of the loss shall not be available as a deduction against any other income of the partner, except that any balance remaining unabsorbed at the end of the tax exempt period of the partnership shall be available as a deduction against any other income of the partner for the year of assessment which relates to the basis period in which the tax exemption ceases and for any subsequent year of assessment in accordance with section 37.\n(5A) Paragraphs (3) and (5) apply only in respect of income from the qualifying activities in paragraphs (a), (b), (c), (g), (h), (i) and (j) of the definition of “qualifying activities” in paragraph (6).\n[S 457/2017 wef 25/03/2016]\n[S 312/2024 wef 12/12/2018]\n(5B) Where an approved partnership incurs a loss on any sale or assignment mentioned in paragraph (d), (e) or (f) of the definition of “qualifying activities” in paragraph (6) in any basis period falling, in whole or in part, within the tax exempt period, that loss may only be deducted against the gains derived from another sale or assignment mentioned in paragraph (d), (e) or (f), as the case may be, in that basis period, and the balance of the loss is not available as a deduction against any other income.\n[S 457/2017 wef 01/06/2011]\n(6) In this regulation —\n“approved international shipping enterprise”, “finance leasing”, “international shipping enterprise”, “shipping investment enterprise”, “Singapore ship” and “tax exempt period” have the same meanings as in section 13P, as modified (where applicable) by paragraph (2);\n[S 457/2017 wef 11/04/2016]\n[S 312/2024 wef 31/12/2021]\n“qualifying activities” means —\n(a)the chartering or finance leasing of any sea-going ship, acquired by the approved partnership before or during the period of its approval referred to in section 13P(3) to —\n(i)a person who is neither resident in Singapore nor a permanent establishment in Singapore; or\n(ii)an approved international shipping enterprise,\nfor use outside the limits of the port of Singapore;\n[S 312/2024 wef 31/12/2021]\n(b)the chartering or finance leasing of any sea-going Singapore ship, acquired by the approved partnership before or during the period of its approval referred to in section 13P(3), to a shipping enterprise within the meaning of section 13A for use outside the limits of the port of Singapore;\n[S 457/2017 wef 01/06/2011]\n[S 312/2024 wef 31/12/2021]\n(c)in respect of income for the year of assessment 2009 and subsequent years of assessment, the foreign exchange and risk management activities which are carried out in connection with and incidental to the activities referred to in paragraphs (a) and (b);\n[S 457/2017 wef 01/06/2011]\n(d)the sale of a sea-going ship;\n[S 457/2017 wef 01/06/2011]\n(e)the assignment to another of all the rights of the approved partnership as the buyer under a contract for the construction of a sea‑going ship;\n[S 457/2017 wef 25/03/2016]\n[S 457/2017 wef 01/06/2011]\n(f)the sale of all of the issued ordinary shares in a special purpose company of the approved partnership where, at the time of the sale of the shares, the special purpose company owns any sea‑going ship or is the buyer under a contract for the construction of any sea‑going ship;\n[S 457/2017 wef 01/06/2011]\n(g)the chartering or finance leasing of any sea-going ship acquired by the approved partnership before or during the period of its approval mentioned in section 13P(3), for use outside the limits of the port of Singapore;\n[S 457/2017 wef 25/03/2016]\n[S 312/2024 wef 12/12/2018]\n[S 312/2024 wef 31/12/2021]\n(h)foreign exchange and risk management activities that are carried out in connection with and incidental to any activity mentioned in paragraph (g);\n[S 457/2017 wef 25/03/2016]\n(i)the chartering or finance leasing by the approved partnership of any sea-going ship, for use by the lessee outside the limits of the port of Singapore, if the ship was —\n(i)acquired by an approved related party of the partnership before or during the period of its approval mentioned in section 13P(3); and\n[S 312/2024 wef 31/12/2021]\n(ii)chartered, or leased under a finance lease, by the approved related party to the approved partnership; and\n[S 312/2024 wef 12/12/2018]\n(j)foreign exchange and risk management activities that are carried out in connection with and incidental to an activity mentioned in paragraph (i);\n[S 312/2024 wef 12/12/2018]\n“related party” means —\n(a)any entity that is related to the approved partnership in the manner prescribed under the Income Tax (Related Party of Approved Container Investment Enterprise under Section 13P) Rules 2021 (G.N. No. S 874/2021), with each reference to an approved shipping investment enterprise replaced with a reference to the approved partnership; and\n[S 312/2024 wef 31/12/2021]\n(b)any other entity that is approved by the Minister in any particular case to be a related party of an approved partnership;\n[S 312/2024 wef 12/12/2018]\n“ship” has the same meaning as in section 13P;\n[S 457/2017 wef 11/04/2016]\n[S 312/2024 wef 31/12/2021]\n“special purpose company”, in relation to an approved partnership, means a company that is wholly owned by the partnership and whose only business or intended business is the chartering or finance leasing of sea‑going ships.\n[S 457/2017 wef 01/06/2011]\n[S 312/2024 wef 31/12/2021]"}},{"id":"SG-H2541-A7","no":7,"noLabel":{"en":"7."},"heading":{"en":"Application of section 19B"},"text":{"en":"7.—(1) Section 19B shall apply for the purpose of making writing-down allowance to any partner of a partnership with the modifications and exceptions set out in this regulation.\n(2) For the purpose of paragraph (1) —\n(a)any reference to a company in section 19B is a reference to the partnership or, in relation to the making of a writing‑down allowance or a charge, to the partners of the partnership;\n(b)the writing-down allowance and charge shall be apportioned to each partner of the partnership according to that partner’s share of the divisible income of the partnership;\n(c)a reference in section 19B to a trade or business of a company is a reference to a trade or business of the partnership;\n(d)a reference in section 19B to the carrying on of a trade or business by a company is a reference to the carrying on of a trade or business by a partnership;\n(da)a reference to a qualifying company for a year of assessment in section 19B(1AD), (1AE) and (1AH) is a reference to the partnership where it is a qualifying partnership for that year of assessment;\n[S 732/2025 wef 30/10/2023]\n(e)a reference to the company in section 19B(2A)(a), (b) and (c) is a reference to the partnership;\n[S 629/2019 wef 25/03/2016]\n(f)a reference to an approved media and digital entertainment company in section 19B(2C) is a reference to a partnership approved by the Minister or an authorised body, whose principal trade or business is to provide media and digital entertainment in Singapore;\n[S 312/2024 wef 12/04/2024]\n(g)any writing-down allowance brought to charge under section 19B(2E), as apportioned to each partner of the partnership according to the partner’s share of divisible income of the partnership, shall be deemed as income of that partner for the year of assessment relating to the basis period in which the event referred to in section 19B(2E) occurs;\n(ga)to avoid doubt, the reference in section 19B(5) to a company to whom writing‑down allowances have been made is a reference to the partnership to whose partners writing‑down allowances have been made;\n[S 629/2019 wef 17/09/2019]\n(h)a reference in section 19B(10A) to a related party of a partnership is a reference to —\n(i)any individual who is a relative of a partner (being an individual) of that partnership;\n(ii)any company which is directly or indirectly controlled by a partner (being an individual) or a relative of a partner of that partnership; or\n(iii)any person who is a related party of a partner (being a person other than an individual) of that partnership; and\n(i)for the avoidance of doubt, a reference to no writing-down allowance to a company in section 19B is a reference to no writing-down allowance to the partners of the partnership.\n(3) For the purpose of section 19B(1A), (1AD), (1B) and (1BAA), where a partnership carrying on a trade or business has incurred capital expenditure during the basis period for any year of assessment between the year of assessment 2011 and the year of assessment 2018 (both years inclusive) or between the year of assessment 2024 and the year of assessment 2028 (both years inclusive) in acquiring one or more intellectual property rights for use in the trade or business, the aggregate of the writing-down allowances that may be allowed to all the partners of the partnership for that expenditure in respect of all the trades and businesses of the partnership shall not exceed the amount computed in accordance with section 19B(1A), (1AD), (1B) or (1BAA) (as the case may be) for that year of assessment.\n[S 629/2019 wef 27/11/2014]\n[S 732/2025 wef 30/10/2023]\n(3A) For the purposes of paragraph (2)(da), the partnership is a qualifying partnership for a year of assessment if —\n(a)where either the partnership is under the control of a single partner who is an individual or no single partner has control over the partnership — the partnership derives less than $500 million in gross revenue from all of the partnership’s trades and businesses in the basis period for that year of assessment; or\n(b)where the partnership is under the control of a single partner that is a company — the partnership, the company and all other entities in the group of which the partnership and the company are parts derive a total of less than $500 million in gross revenue from all of their trades and businesses in that basis period.\n[S 732/2025 wef 30/10/2023]\n(3B) In paragraph (3A), whether or not the partnership is under the control of a partner is determined in accordance with FRS 110.\n[S 732/2025 wef 30/10/2023]\n(3C) For the purposes of paragraphs (3A) and (3B) —\n“FRS 110” means the financial reporting standard known as Financial Reporting Standard 110 (Consolidated Financial Statements) that is treated as made by the Accounting Standards Committee under Part 3 of the Accounting Standards Act 2007, as amended from time to time; and\n“group” means a group of entities (whether incorporated or registered in Singapore or elsewhere) comprising a parent and its subsidiaries within the meaning of FRS 110.\n[S 732/2025 wef 30/10/2023]\n(4) Without prejudice to section 19B(10A), where —\n(a)a partnership (referred to in this paragraph as the first-mentioned partnership) has acquired the intellectual property rights from another partnership (referred to in this paragraph as the second-mentioned partnership) directly or indirectly from a related party of the second-mentioned partnership; and\n(b)a partner of the first-mentioned partnership —\n(i)being an individual, is a relative of one or more of the partners of the second-mentioned partnership (being individuals) who comes within paragraph (5);\n(ii)being an individual, directly or indirectly controls one or more of the partners of the second-mentioned partnership (being companies) who comes within paragraph (5); or\n(iii)being a person other than an individual, is a related party of one or more of the partners of the second‑mentioned partnership and that partner or those partners of the second-mentioned partnership who comes within paragraph (5),\nno writing-down allowance under section 19B shall be made to the partners of the first-mentioned partnership for any capital expenditure incurred by the first-mentioned partnership in such acquisition.\n(5) In paragraph (4), a partner of the second-mentioned partnership comes within this paragraph if the partner is one —\n(a)to whom any deduction has been allowed under section 14, 14C, 14D, 14E, 14EA or 14P for any outgoing, expense or payment incurred for any activity which resulted in the creation of the intellectual property; and\n[S 312/2024 wef 31/12/2021]\n[S 732/2025 wef 30/10/2023]\n(b)whose share of the proceeds from the sale, transfer or assignment of those intellectual property rights to the first‑mentioned partnership are not chargeable to tax.\n(6) In this regulation —\n“capital expenditure” and “intellectual property rights” have the same meanings as in section 19B(11);\n“child” includes a step-child, a child who has been de facto adopted by the partner or by the spouse of the partner, whether or not such adoption has been registered in accordance with the provisions of any written law, and a child of whom the partner has the custody or whom he maintains wholly or partly at his own expense;\n[Deleted by S 732/2025 wef 04/11/2022]\n“relative”, in relation to a partner who is an individual, means any person who is a spouse, parent, child, grandchild, brother, sister, uncle, aunt, nephew, niece, cousin of the partner."}},{"id":"SG-H2541-A8","no":8,"noLabel":{"en":"8."},"heading":{"en":"Application of section 43N"},"text":{"en":"8.—(1) Section 43N shall apply to the share of divisible income of a partner of an approved partnership which is an aircraft leasing partnership, from any activity referred to in section 43N(1) as it applies to the income of an approved aircraft leasing company with the modifications and exceptions set out in regulation 3 and this regulation.\n[S 312/2024 wef 31/12/2021]\n(2) For the purpose of paragraph (1), paragraph (3) shall apply in lieu of section 43N(5), and section 43N(6) shall be construed accordingly.\n[S 312/2024 wef 31/12/2021]\n(3) In determining the share of divisible income of a partner of an approved partnership that is subject to tax at the concessionary rate of tax under section 43N(1) —\n(a)the allowances under section 19, 19A, 20, 21, 22 or 23, as apportioned to that share, shall be taken into account notwithstanding that no claim for such allowances has been made;\n[S 312/2024 wef 12/04/2024]\n(b)the allowances under section 19, 19A, 20, 21, 22 or 23 in respect of finance leasing in any year of assessment, as apportioned to the share of divisible income of the partner from finance leasing for that year of assessment, shall be deducted against that share, and any balance of the allowances shall not, subject to sub-paragraph (c), be available as a deduction against any other income of the partner or be available for transfer under section 37B;\n[S 312/2024 wef 31/12/2021]\n[S 312/2024 wef 12/04/2024]\n(c)where the approved partnership ceases to derive income from finance leasing in the basis period for any year of assessment, any balance of the allowances in respect of such finance leasing after the deduction against the share of divisible income of the partner from that finance leasing shall be available as a deduction against any other income of the partner for that year of assessment and for any subsequent year of assessment in accordance with section 23; and\n(d)the Comptroller shall determine the manner and extent to which —\n(i)allowance under section 19, 19A, 20, 21, 22 or 23, and any expense and donation allowable under the Act are to be deducted; and\n[S 312/2024 wef 12/04/2024]\n(ii)any loss may be deducted under section 37.\n[S 312/2024 wef 31/12/2021]\n(4) In this regulation —\n“aircraft leasing partnership” means a partnership registered under any written law in Singapore, carrying on a business of leasing aircrafts or aircraft engines within the meaning of section 43N;\n“finance leasing” has the meaning given by section 43N.\n[S 312/2024 wef 31/12/2021]\n[S 312/2024 wef 12/04/2024]"}},{"id":"SG-H2541-A9","no":9,"noLabel":{"en":"9."},"heading":{"en":"Application of section 43P"},"text":{"en":"9.—(1) Section 43P shall apply to the share of divisible income of a partner of an approved partnership from qualifying activities, as it applies to the income of an approved container investment enterprise from the activities referred to in section 43P(1)(a), (b), (c), (d), (e), (f) and (g), with the modifications and exceptions set out in regulation 3 and this regulation.\n[S 457/2017 wef 15/08/2017]\n[S 312/2024 wef 12/12/2018]\n[S 312/2024 wef 31/12/2021]\n(2) For the purposes of paragraph (1) —\n(a)the reference in section 43P(3) to a container investment enterprise is a reference to a partnership registered under any written law in Singapore;\n[S 312/2024 wef 31/12/2021]\n(b)a reference in section 43P to the approval of a container investment enterprise is a reference to the approval of the partnership under section 43P(3);\n[S 312/2024 wef 31/12/2021]\n(c)a reference in section 43P to a container or an intermodal equipment acquired or leased by an approved container investment enterprise is a reference to a container or an intermodal equipment acquired or leased by the approved partnership; and\n[S 457/2017 wef 15/08/2017]\n[S 312/2024 wef 31/12/2021]\n(d)paragraphs (3), (3A) and (4) apply in lieu of section 43P(2), (2A), (2B), (2C) and (6).\n[S 312/2024 wef 12/12/2018]\n[S 312/2024 wef 31/12/2021]\n(3) Section 43P(1) shall continue to apply to a partner of a partnership the approval of which has expired or been withdrawn, but which continues to derive income from qualifying activities in relation to a container or an intermodal equipment acquired before or during the period of the approval, provided that the partnership has, or (in the case of income derived from any activity mentioned in paragraph (e), (f) or (g) of the definition of “qualifying activities” in paragraph (5)) both the partnership and the approved related party have, by the date of the expiry or before the withdrawal, fulfilled all the conditions referred to in section 43P(4); and any reference in section 43P and these Regulations to an approved partnership shall be construed accordingly.\n[S 457/2017 wef 15/08/2017]\n[S 312/2024 wef 12/12/2018]\n[S 312/2024 wef 31/12/2021]\n(3A) Section 43P(1)(a), (c), (e) and (f) does not apply to income derived on or after 12 December 2018 from the leasing of a container or intermodal equipment that is acquired by the approved partnership or the approved related party by way of a finance lease entered into with an entity that was not an approved related party.\n[S 312/2024 wef 12/12/2018]\n[S 312/2024 wef 31/12/2021]\n(4) In determining the share of divisible income of a partner of an approved partnership that is subject to tax at the concessionary rate of tax under section 43P(1) —\n(a)the allowances under section 19, 19A, 20, 21, 22 or 23 (other than allowances made to the lessee under regulations made under section 10C), as apportioned to that share, shall be taken into account notwithstanding that no claim for such allowances has been made;\n[S 457/2017 wef 24/02/2015]\n[S 312/2024 wef 31/12/2021]\n[S 312/2024 wef 12/04/2024]\n(b)the allowances under section 19, 19A, 20, 21, 22 or 23 (other than allowances made to the lessee under regulations made under section 10C) in respect of finance leasing in any year of assessment, as apportioned to the share of divisible income of the partner from finance leasing for that year of assessment, shall be deducted against that share, and any balance of the allowances shall not, subject to sub-paragraph (c), be available as a deduction against any other income of the partner or be available for transfer under section 37B;\n[S 457/2017 wef 24/02/2015]\n[S 312/2024 wef 31/12/2021]\n[S 312/2024 wef 12/04/2024]\n(c)where the approved partnership ceases to derive income from finance leasing in the basis period for any year of assessment, any balance of the allowances in respect of such finance leasing after the deduction against the share of divisible income of the partner from that finance leasing shall be available as a deduction against any other income of the partner for that year of assessment and for any subsequent year of assessment in accordance with section 23; and\n(d)the Comptroller shall determine the manner and extent to which —\n(i)allowances under section 19, 19A, 20, 21, 22 or 23, and any expenses and donations allowable under the Act are to be deducted; and\n[S 312/2024 wef 12/04/2024]\n(ii)any loss may be deducted under section 37.\n[S 312/2024 wef 31/12/2021]\n(5) In this regulation —\n“container”, “container investment enterprise” and “finance leasing” have the same meanings as in section 43P;\n[S 312/2024 wef 31/12/2021]\n“intermodal equipment” has the same meaning as in section 43P;\n[S 457/2017 wef 15/08/2017]\n[S 312/2024 wef 31/12/2021]\n“qualifying activities” means —\n(a)the leasing of any container owned by the approved partnership acquired before or during the period of approval of the partnership referred to in section 43P(4) and used for the international transportation of goods;\n[S 457/2017 wef 15/08/2017]\n[S 312/2024 wef 31/12/2021]\n(b)the foreign exchange and risk management activities which are carried out in connection with and incidental to the leasing referred to in paragraph (a);\n[S 457/2017 wef 15/08/2017]\n(c)for the year of assessment 2013 and subsequent years of assessment, the leasing of any intermodal equipment owned by the approved partnership acquired before or during the period of approval of the partnership mentioned in section 43P(4), that is incidental to the leasing mentioned in paragraph (a);\n[S 457/2017 wef 15/08/2017]\n[S 312/2024 wef 12/12/2018]\n[S 312/2024 wef 31/12/2021]\n(d)for the year of assessment 2013 and subsequent years of assessment, foreign exchange and risk management activities that are carried out in connection with and incidental to the leasing mentioned in paragraph (c);\n[S 457/2017 wef 15/08/2017]\n[S 312/2024 wef 12/12/2018]\n[S 312/2024 wef 31/12/2021]\n(e)the leasing of any container used for international transportation of goods, if the container was —\n(i)acquired by an approved related party before or during the period of the approval of the related party under section 43P(4); and\n[S 312/2024 wef 31/12/2021]\n(ii)leased by the approved related party to the approved partnership;\n[S 312/2024 wef 12/12/2018]\n(f)the leasing of any intermodal equipment that is incidental to the lease mentioned in paragraph (e), if the intermodal equipment was —\n(i)acquired by an approved related party before or during the period of the approval of the related party under section 43P(4); and\n[S 312/2024 wef 31/12/2021]\n(ii)leased by the approved related party to the approved partnership; and\n[S 312/2024 wef 12/12/2018]\n(g)foreign exchange and risk management activities that are carried out in connection with and incidental to the leases mentioned in paragraphs (e) and (f);\n[S 312/2024 wef 12/12/2018]\n“related party” means —\n(a)any entity that is related to the approved partnership in the manner prescribed under the Income Tax (Related Party of Approved Container Investment Enterprise under Section 43P) Rules 2021 (G.N. No. S 875/2021); and\n[S 312/2024 wef 31/12/2021]\n(b)any other entity that is approved by the Minister in any particular case to be a related party of an approved partnership.\n[S 312/2024 wef 12/12/2018]\n[S 312/2024 wef 31/12/2021]"}}],"pack":"sg-p32","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1749-SG-1200","source":"Income Tax (Tax Incentives for Partnerships) Regulations 2012","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2542"] = {"id":"SG-H2542","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S732-2022?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（Tetra Pak Asia 私人有限公司依第 13（12）条享有的豁免）命令 2022","en":"Income Tax (Tetra Pak Asia Pte Ltd — Section 13(12) Exemption) Order 2022","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S732-2022","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2542-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order is the Income Tax (Tetra Pak Asia Pte Ltd — Section 13(12) Exemption) Order 2022."}},{"id":"SG-H2542-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2.—(1) Income comprising dividends amounting to $22,672,059 that is received in Singapore by Tetra Pak Asia Pte Ltd (a company incorporated in Singapore) from Tetra Pak Manufacturing Pty. Limited (a company incorporated in Australia) in the basis periods for the years of assessment 2017 to 2020 is exempt from tax.\n(2) The exemption in sub-paragraph (1) is subject to the terms and conditions specified in the letter of approval dated 5 May 2022 addressed to EY Corporate Advisors Pte. Ltd."}}],"pack":"sg-p32","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Tetra Pak Asia Pte Ltd — Section 13(12) Exemption) Order 2022","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2543"] = {"id":"SG-H2543","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S906-2024?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（Thakral 私人有限公司依第 13（12）条享有的豁免）命令 2024","en":"Income Tax (Thakral Pte. Ltd. — Section 13(12) Exemption) Order 2024","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S906-2024","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2543-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order is the Income Tax (Thakral Pte. Ltd. — Section 13(12) Exemption) Order 2024."}},{"id":"SG-H2543-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2.—(1) Dividend income received in Singapore by Thakral Pte. Ltd. (a company incorporated in Singapore) on or after 15 May 2024 from Orion Elektronikai Kft. (a company incorporated in Hungary), is exempt from tax.\n(2) The exemption in sub‑paragraph (1) is subject to the conditions specified in the letter from the Inland Revenue Authority of Singapore dated 7 November 2024 that is issued on behalf of the Minister for Finance and addressed to HLS Tax Advisory Services Pte Ltd."}}],"pack":"sg-p32","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Thakral Pte. Ltd. — Section 13(12) Exemption) Order 2024","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2544"] = {"id":"SG-H2544","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S86-2023?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（Tiger Holdco 私人有限公司依第 13（4）条享有的豁免）公告 2023","en":"Income Tax (Tiger Holdco Pte. Ltd. — Section 13(4) Exemption) Notification 2023","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S86-2023","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2544-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. This Notification is the Income Tax (Tiger Holdco Pte. Ltd. — Section 13(4) Exemption) Notification 2023 and is deemed to have come into operation on 18 March 2021."}},{"id":"SG-H2544-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2.—(1) The interest payable by Tiger Holdco Pte. Ltd. during the period from 18 March 2021 to 10 June 2023 (both dates inclusive) in respect of the amount of US$233 million under a bond agreement dated 17 March 2021, that is used for the purpose of on‑lending to Armada 98/2 Pte. Ltd. to finance the conversion and refurbishment of a large crude carrier vessel to a Singapore‑flagged Floating, Production, Storage and Offloading vessel named “Armada Sterling V”, is exempt from tax.\n(2) The exemption in sub-paragraph (1) is subject to the conditions specified in the letter from the Ministry of Finance dated 20 January 2023 and addressed to Deloitte Tax Solutions Pte. Ltd."}}],"pack":"sg-p32","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Tiger Holdco Pte. Ltd. — Section 13(4) Exemption) Notification 2023","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2545"] = {"id":"SG-H2545","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S792-2020?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（TN Asia 私人有限公司依第 13（12）条享有的豁免）命令 2020","en":"Income Tax (TN Asia Pte. Ltd. — Section 13(12) Exemption) Order 2020","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S792-2020","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2545-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order is the Income Tax (TN Asia Pte. Ltd. — Section 13(12) Exemption) Order 2020."}},{"id":"SG-H2545-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2.—(1) Income comprising dividends amounting to EURO 3,100,000 that is received in Singapore by TN Asia Pte. Ltd. (a company incorporated in Singapore) from TN Europe, B.V. (a company incorporated in the Netherlands) in the basis period for year of assessment 2019 is exempt from tax.\n(2) The exemption in sub‑paragraph (1) is subject to the terms and conditions specified in the letter of approval dated 11 August 2020 addressed to PricewaterhouseCoopers Singapore Pte. Ltd."}}],"pack":"sg-p32","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (TN Asia Pte. Ltd. — Section 13(12) Exemption) Order 2020","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2546"] = {"id":"SG-H2546","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S678-2021?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（Total Engine 资产管理私人有限公司——第 13(4) 条豁免）公告 2021","en":"Income Tax (Total Engine Asset Management Pte. Ltd. — Section 13(4) Exemption) Notification 2021","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S678-2021","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2546-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. This Notification is the Income Tax (Total Engine Asset Management Pte. Ltd. — Section 13(4) Exemption) Notification 2021 and is deemed to have come into operation on 26 July 2019."}},{"id":"SG-H2546-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2.—(1) The interest and legal fee payable by Total Engine Asset Management Pte. Ltd. —\n(a)to the respective lenders mentioned in the first column of the following table;\n(b)in respect of the respective loan amounts mentioned in the second column of the table that are or are to be used to finance the acquisition of the respective aircraft engines mentioned in the third column of the table;\n(c)under the respective agreements mentioned in the fourth column of the table; and\n(d)that are due and payable during the respective periods mentioned in the fifth column of the table,\nare exempt from tax:\nFirst column\nSecond column\nThird column\nFourth column\nFifth column\nLender\nLoan amount\n(US$)\nAircraft engines\nAgreement\nPeriod\n(both dates inclusive)\nLemon Gas Co., Ltd.\n16,050,000\n“SN 598977”\nLoan agreement dated 24 July 2019\n26 July 2019 to 24 June 2020\nChishima Real Estate Co., Ltd.\n16,050,000\n“SN 599218”\nLoan agreement dated 27 September 2019\n30 September 2019 to 28 August 2020\n(2) The exemption under sub‑paragraph (1) is subject to the conditions specified in the letter of approval dated 21 September 2020 issued by the Ministry of Finance and addressed to Total Engine Asset Management Pte. Ltd."}}],"pack":"sg-p32","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Total Engine Asset Management Pte. Ltd. — Section 13(4) Exemption) Notification 2021","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2547"] = {"id":"SG-H2547","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S893-2024?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（Total Engine 资产管理私人有限公司——第 13(4) 条豁免）公告 2024","en":"Income Tax (Total Engine Asset Management Pte. Ltd. — Section 13(4) Exemption) Notification 2024","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S893-2024","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2547-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. This Notification is the Income Tax (Total Engine Asset Management Pte. Ltd. — Section 13(4) Exemption) Notification 2024 and is deemed to have come into operation on 19 August 2022."}},{"id":"SG-H2547-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2.—(1) The interest of US$35,586.18 payable by Total Engine Asset Management Pte. Ltd. to TEAM United Kingdom 01 Limited during the period from 19 August 2022 to 29 March 2024 (both dates inclusive) in respect of the loan amount of US$350,000 under the loan agreement dated 29 March 2019 between Total Engine Asset Management Pte. Ltd. and TEAM United Kingdom 01 Limited for financing the purchase of 2 aircraft engines bearing the manufacturer’s serial numbers ESN 59B010 and ESN 599515, respectively, is exempt from tax.\n(2) The exemption in sub‑paragraph (1) is subject to the conditions specified in the letter from the Ministry of Finance dated 23 October 2024 and addressed to KPMG Services Pte. Ltd."}}],"pack":"sg-p32","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Total Engine Asset Management Pte. Ltd. — Section 13(4) Exemption) Notification 2024","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2548"] = {"id":"SG-H2548","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S488-2020?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（Trafigura Group 私人有限公司——第 13(4) 条豁免）（第 2 号）公告 2020","en":"Income Tax (Trafigura Group Pte Ltd — Section 13(4) Exemption) (No. 2) Notification 2020","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S488-2020","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2548-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. This Notification is the Income Tax (Trafigura Group Pte Ltd — Section 13(4) Exemption) (No. 2) Notification 2020 and is deemed to have come into operation on 27 April 2018."}},{"id":"SG-H2548-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2.—(1) Subject to sub‑paragraph (3), the interest, commission, fee and other payments payable by Trafigura Group Pte Ltd to any person who is not resident in Singapore —\n(a)in connection with the bonds denominated in Chinese Renminbi and issued in the People’s Republic of China by Trafigura Group Pte Ltd that are specified in sub‑paragraph (2); or\n(b)in connection with any arrangement, management, guarantee, or services relating to such bonds,\nthat are due and payable up to (and including) the date of maturity of the bonds, are exempt from tax.\n(2) The bonds in sub‑paragraph (1) are those —\n(a)issued on the dates mentioned in the first column of the following table;\n(b)maturing on the respective dates mentioned in the second column of the table; and\n(c)having the respective issue sizes mentioned in the third column of the table:\nFirst column\nSecond column\nThird column\nDate of issue\nDate of maturity\nIssue size (RMB)\n27 April 2018\n27 April 2021\n500 million\n24 May 2018\n24 May 2021\n500 million\n28 Sep 2018\n28 Sep 2021\n700 million\n20 May 2019\n20 May 2022\n540 million\n(3) The exemption under sub‑paragraph (1) does not apply to —\n(a)any interest, commission, fee or other payments derived from any operation carried on by the person through the person’s permanent establishment in Singapore; or\n(b)any interest, commission, fee or other payments that are due and payable after the date on which Trafigura Pte Ltd (a subsidiary of Trafigura Group Pte Ltd) ceases to be an approved global trading company under section 43P of the Act.\n(4) The exemption in sub‑paragraph (1) is subject to the conditions specified in the letter of approval dated 4 January 2017 issued by the International Enterprise Singapore Board addressed to Trafigura Group Pte Ltd."}}],"pack":"sg-p32","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Trafigura Group Pte Ltd — Section 13(4) Exemption) (No. 2) Notification 2020","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2549"] = {"id":"SG-H2549","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S487-2020?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"所得税（Trafigura Group 私人有限公司——第 13(4) 条豁免）公告 2020","en":"Income Tax (Trafigura Group Pte Ltd — Section 13(4) Exemption) Notification 2020","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S487-2020","completenessNote":"全文，共 3 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2549-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. This Notification is the Income Tax (Trafigura Group Pte Ltd — Section 13(4) Exemption) Notification 2020 and is deemed to have come into operation on 30 September 2015."}},{"id":"SG-H2549-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Definition"},"text":{"en":"2. In this Notification, “applicable securities” means the Perpetual Resettable Step‑up Subordinated Securities having an issue size of US$500 million issued by Trafigura Beheer B.V. in accordance with the Offering Circular dated 17 April 2013 as amended on 2 September 2015."}},{"id":"SG-H2549-A3","no":3,"noLabel":{"en":"3."},"heading":{"en":"Exemption"},"text":{"en":"3.—(1) Subject to sub-paragraph (2), the interest, commission, fee and other payments payable by Trafigura Group Pte Ltd to any person who is not resident in Singapore on or after 30 September 2015 —\n(a)in connection with the applicable securities; or\n(b)in connection with any arrangement, management, guarantee or services relating to the applicable securities,\nare exempt from tax.\n(2) The exemption under sub-paragraph (1) does not apply to —\n(a)any interest, commission, fee or other payments derived from any operation carried on by the person through the person’s permanent establishment in Singapore; or\n(b)any interest, commission, fee or other payments that are due and payable after the date on which Trafigura Pte Ltd (a subsidiary of Trafigura Group Pte Ltd) ceases to be an approved global trading company under section 43P of the Act.\n(3) The exemption under sub‑paragraph (1) is subject to the conditions specified in the letter of approval dated 12 August 2015 issued by International Enterprise Singapore Board addressed to Trafigura Group Pte Ltd."}}],"pack":"sg-p32","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Trafigura Group Pte Ltd — Section 13(4) Exemption) Notification 2020","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2550"] = {"id":"SG-H2550","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S3-2025?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"所得税（Trafigura Group 私人有限公司等——第 13(4) 条豁免）公告 2025","en":"Income Tax (Trafigura Group Pte. Ltd., etc. — Section 13(4) Exemption) Notification 2025","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S3-2025","completenessNote":"全文，共 3 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2550-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. This Notification is the Income Tax (Trafigura Group Pte. Ltd., etc. — Section 13(4) Exemption) Notification 2025 and is deemed to have come into operation on 1 January 2018."}},{"id":"SG-H2550-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Definitions"},"text":{"en":"2. In this Notification —\n“relevant person” means Trafigura Group Pte. Ltd., Trafigura Pte Ltd or a satellite entity;\n“satellite entity” means any of the following:\n(a)Trafigura Maritime Logistics Pte. Ltd.;\n(b)Trafigura Commodities Funding Pte. Ltd.;\n(c)TFG Marine Pte. Ltd.;\n(d)Trafigura Asia Trading Pte. Ltd.;\n(e)Trafigura Global Commodities Funding Pte. Ltd.;\n(f)CB Enterprises Pte. Ltd.;\n(g)Pan‑African Soleil Holdings Pte. Ltd.;\n(h)Puma Energy Irrawaddy Holding Pte. Ltd.;\n(i)Puma Energy Supply & Trading Pte. Ltd.;\n“specified loan or indebtedness” means any loan or indebtedness that —\n(a)is incurred by a relevant person to a non‑resident person;\n(b)is incurred for the purpose of a trading activity or trading‑related activity;\n(c)arises under or in connection with any of the following:\n(i)a corporate security, including a medium term note or a variable funding note;\n(ii)a private placement of securities;\n(iii)a perpetual security;\n(iv)a term loan;\n(v)a revolving credit facility;\n(vi)an asset securitisation arrangement;\n(vii)a repurchase agreement;\n(viii)a borrowing base facility;\n(ix)a bilateral line facility; and\n(d)is notified to the Inland Revenue Authority of Singapore and the Enterprise Singapore Board at any time on or after 1 January 2018 but on or before 30 September 2021;\n“trading activity” means any activity carried on in the course of a business of international trading of commodities or commodities derivatives, including —\n(a)the financing of inventories;\n(b)the financing of trade receivables; and\n(c)the financing of working capital used specifically for trading purposes, including —\n(i)overheads;\n(ii)storage;\n(iii)margin calls on derivative positions; and\n(iv)any other activity undertaken by any relevant person,\nbut excluding working capital used for the cost of utilities, the cost of Internet services or any other purpose that does not specifically relate to trading purposes;\n“trading‑related activity” means any investment in or construction of any asset, carried on by a relevant person, that supports a trading activity, including —\n(a)any investment in or construction of infrastructure that supports trading activities such as vessels, oil terminals and warehouses; and\n(b)any investment in or construction of infrastructure that supports commodity customers and commodity suppliers of trading activities, such as service stations and mines."}},{"id":"SG-H2550-A3","no":3,"noLabel":{"en":"3."},"heading":{"en":"Exemption"},"text":{"en":"3.—(1) Subject to sub‑paragraphs (2), (4) and (5), any interest, commission, fee or other payment that is payable by a relevant person to any non‑resident person (A) in connection with any specified loan or indebtedness entered into or incurred by any relevant person between 1 January 2018 and 30 September 2021 (both dates inclusive), is exempt from tax.\n(2) The exemption in sub‑paragraph (1) only applies —\n(a)where the total amount of all the specified loans or indebtedness mentioned in sub‑paragraph (1) exceeds US$10 billion — to any interest, commission, fee or other payment mentioned in that sub‑paragraph, that is payable on the first US$10 billion that is disbursed;\n(b)if each specified loan or indebtedness is $5 million or more;\n(c)if each specified loan or indebtedness is entered into between the lender and the borrower on an arm’s length basis;\n(d)subject to sub‑paragraph (3), where A is a related party of the borrower, if at the time the interest, commission, fee or other payment is payable to A, the highest rate of tax of a similar character to income tax (by whatever name called) that is levied —\n(i)under the law of the territory that A is a tax resident in; and\n(ii)on any gains or profits from any trade or business carried on by A in that territory at that time,\nis more than 0%; and\n(e)if the interest rate for each specified loan or indebtedness is comparable to the market rate for other similar loans or indebtedness, if any.\n(3) Sub‑paragraph (2)(d) does not apply to any specified loan or indebtedness that is a bond unless that bond is only issued to one or more related parties of the borrower.\n(4) The exemption in sub‑paragraph (1) does not apply to —\n(a)any interest, commission, fee or other payment derived from any operation carried on by A through A’s permanent establishment in Singapore; or\n(b)any interest, commission, fee or other payment that is due and payable after the earliest of the following:\n(i)the date of maturity of the specified loan or indebtedness;\n(ii)30 September 2026;\n(iii)the last date on which Trafigura Pte Ltd is an approved global trading company under section 43I of the Act.\n(5) The exemption in sub‑paragraph (1) is subject to the conditions specified in the letter from the Ministry of Finance dated 3 December 2019 and addressed to Trafigura Pte Ltd."}}],"pack":"sg-p32","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Trafigura Group Pte. Ltd., etc. — Section 13(4) Exemption) Notification 2025","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2551"] = {"id":"SG-H2551","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S2-2020?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（Trafigura 控股私人有限公司依第 13（12）条享有的豁免）命令 2020","en":"Income Tax (Trafigura Holdings Pte Ltd — Section 13(12) Exemption) Order 2020","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S2-2020","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2551-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order is the Income Tax (Trafigura Holdings Pte Ltd — Section 13(12) Exemption) Order 2020."}},{"id":"SG-H2551-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2.—(1) Dividends received in Singapore by Trafigura Holdings Pte Ltd (a company incorporated in Singapore) during its financial year that ended on 30 September 2016 from Trafigura BV (a company incorporated in the Netherlands), which were derived from dividends received by Trafigura BV from Trafigura Pte Ltd (a company incorporated in Singapore), are exempt from tax.\n(2) The exemption in sub‑paragraph (1) is subject to the conditions specified in the letter of approval dated 23 July 2018 addressed to PricewaterhouseCoopers Singapore Pte Ltd, the representative of Trafigura Holdings Pte Ltd."}}],"pack":"sg-p32","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Trafigura Holdings Pte Ltd — Section 13(12) Exemption) Order 2020","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2552"] = {"id":"SG-H2552","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S624-2021?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（Trafigura 控股私人有限公司依第 13（12）条享有的豁免）命令 2021","en":"Income Tax (Trafigura Holdings Pte Ltd — Section 13(12) Exemption) Order 2021","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S624-2021","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2552-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order is the Income Tax (Trafigura Holdings Pte Ltd — Section 13(12) Exemption) Order 2021."}},{"id":"SG-H2552-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2.—(1) Dividend income received in Singapore by Trafigura Holdings Pte Ltd during and after its financial year ended 30 September 2017 from Trafigura BV (a company incorporated in the Netherlands), which is in turn derived from dividend income received by Trafigura BV from the profits of Trafigura Pte Ltd, is exempt from tax.\n(2) Dividend income received in Singapore by Trafigura Holdings Pte Ltd during and after its financial year ended 30 September 2019 from Trafigura BV, which is in turn derived from dividend income received by Trafigura BV from the profits of any of the following companies, is exempt from tax:\n(a)Puma Energy Holdings Pte Ltd;\n(b)Pan-African Soleil Holdings Pte Ltd;\n(c)Galena Asset Management (Asia) Pte Ltd;\n(d)Trafigura Overseas Projects Pte Ltd.\n(3) The exemptions under sub-paragraphs (1) and (2) are subject to the conditions specified in the letter of approval dated 20 May 2020 addressed to KPMG Services Pte. Ltd."}}],"pack":"sg-p32","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Trafigura Holdings Pte Ltd — Section 13(12) Exemption) Order 2021","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2553"] = {"id":"SG-H2553","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S663-2023?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（Trafigura 控股私人有限公司依第 13（12）条享有的豁免）命令 2023","en":"Income Tax (Trafigura Holdings Pte Ltd — Section 13(12) Exemption) Order 2023","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S663-2023","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2553-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order is the Income Tax (Trafigura Holdings Pte Ltd — Section 13(12) Exemption) Order 2023."}},{"id":"SG-H2553-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemptions"},"text":{"en":"2.—(1) Dividend income received in Singapore by Trafigura Holdings Pte Ltd (a company incorporated in Singapore) after 1 December 2019 from Cortes Investments S.á.r.l. (a company incorporated in Luxembourg), which is in turn derived from the profits of any of the following companies, is exempt from tax:\n(a)Galena Asset Management (Asia) Pte Ltd (a company incorporated in Singapore);\n(b)Puma Energy Holdings Pte Ltd (a company incorporated in Singapore);\n(c)Trafigura Pte Ltd (a company incorporated in Singapore);\n(d)Trafigura Overseas Project Pte Ltd (a company incorporated in Singapore).\n(2) Dividend income received in Singapore by Trafigura Holdings Pte Ltd after 1 December 2019 from Trafigura Holdings Limited (a company incorporated in Malta), which is in turn derived from the profits of Pan‑African Soleil Holdings Pte Ltd (a company incorporated in Singapore), is exempt from tax.\n(3) The exemptions in sub-paragraphs (1) and (2) are subject to the conditions specified in the letters from the Ministry of Finance dated 29 August 2023 and 3 October 2023, and addressed to KPMG Services Pte. Ltd."}}],"pack":"sg-p32","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Trafigura Holdings Pte Ltd — Section 13(12) Exemption) Order 2023","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2554"] = {"id":"SG-H2554","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S19-2024?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（Trafigura 控股私人有限公司依第 13（12）条享有的豁免）命令 2024","en":"Income Tax (Trafigura Holdings Pte. Ltd. — Section 13(12) Exemption) Order 2024","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S19-2024","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2554-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order is the Income Tax (Trafigura Holdings Pte. Ltd. — Section 13(12) Exemption) Order 2024."}},{"id":"SG-H2554-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2.—(1) Dividend income received in Singapore by Trafigura Holdings Pte. Ltd. (a company incorporated in Singapore) after 1 December 2023 from Cortes Investments S.á.r.l. (a company incorporated in Luxembourg), which is in turn derived from the profits of Iberian Holdings SA (a company incorporated in Switzerland), is exempt from tax.\n(2) The exemption in sub‑paragraph (1) is subject to the conditions specified in the letter from the Ministry of Finance dated 1 December 2023 and addressed to KPMG Services Pte. Ltd."}}],"pack":"sg-p32","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Trafigura Holdings Pte. Ltd. — Section 13(12) Exemption) Order 2024","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2555"] = {"id":"SG-H2555","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S630-2025?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（Trafigura 私人有限公司依第 13（12）条享有的豁免）命令 2025","en":"Income Tax (Trafigura Pte Ltd — Section 13(12) Exemption) Order 2025","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S630-2025","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2555-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order is the Income Tax (Trafigura Pte Ltd — Section 13(12) Exemption) Order 2025."}},{"id":"SG-H2555-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2.—(1) The following income received in Singapore by Trafigura Pte Ltd (a company incorporated in Singapore) is exempt from tax:\n(a)dividend income received on 6 September 2022 from Trafigura Ventures V B.V. (a company incorporated in the Netherlands), which is in turn derived from the profits of Trafigura Chile Limitada (a company incorporated in Chile);\n(b)dividend income received on 29 September 2022 from Trafigura Ventures V B.V., which is in turn derived from the profits of Trafigura Services South Africa (Pty) Ltd (a company incorporated in South Africa).\n(2) The exemption in sub‑paragraph (1) is subject to the conditions specified in the letter from the Inland Revenue Authority of Singapore dated 29 August 2025 that is issued on behalf of the Minister for Finance and addressed to Trafigura Pte Ltd."}}],"pack":"sg-p32","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Trafigura Pte Ltd — Section 13(12) Exemption) Order 2025","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2556"] = {"id":"SG-H2556","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S30-2026?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（Trafigura 私人有限公司依第 13（12）条享有的豁免）命令 2026","en":"Income Tax (Trafigura Pte Ltd — Section 13(12) Exemption) Order 2026","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S30-2026","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2556-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order is the Income Tax (Trafigura Pte Ltd — Section 13(12) Exemption) Order 2026."}},{"id":"SG-H2556-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2.—(1) Branch profits received in Singapore by Trafigura Pte Ltd (a company incorporated in Singapore) on or after 2 January 2026 from its branches in Montevideo, Uruguay and Dubai, United Arab Emirates are exempt from tax.\n(2) The exemption in sub‑paragraph (1) is subject to the conditions specified in the letter from the Inland Revenue Authority of Singapore dated 2 January 2026 that is issued on behalf of the Minister for Finance and addressed to Trafigura Pte Ltd."}}],"pack":"sg-p32","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Trafigura Pte Ltd — Section 13(12) Exemption) Order 2026","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2557"] = {"id":"SG-H2557","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-OR35?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":1,"structureMode":"WHOLE","title":{"zh":"所得税（银行或金融公司转让业务）（合并）命令","en":"Income Tax (Transfer of Undertaking by Bank or Finance Company) (Consolidation) Order","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-OR35","completenessNote":"该法规为单篇法律文书，无分节结构；正文按官方 front 抬头逐字全录，共 1 条。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2557-A1","no":1,"noLabel":{"en":"1"},"text":{"en":"Income Tax Act\n(Chapter 134, Section 14I(3))\nIncome Tax (Transfer of Undertaking by Bank or Finance Company) (Consolidation) Order\nO 35\nG.N. No. S 19/1998\nREVISED EDITION 1994\n(31st January 2000)"}}],"pack":"sg-p32","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Transfer of Undertaking by Bank or Finance Company) (Consolidation) Order","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2558"] = {"id":"SG-H2558","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S510-2000?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（银行或金融公司转让业务）（第 10 号）命令 2000","en":"Income Tax (Transfer of Undertaking by Bank or Finance Company) (No. 10) Order 2000","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S510-2000","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2558-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order may be cited as the Income Tax (Transfer of Undertaking by Bank or Finance Company) (No. 10) Order 2000."}},{"id":"SG-H2558-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Declaration of provisions in accounts"},"text":{"en":"2. It is hereby declared that under section 14I(3) of the Act, the provisions in the account of United Overseas Finance Limited which have been transferred to United Overseas Bank Limited —\n(a)shall not be deemed under section 14I(2)(b) of the Act to be a trading receipt of United Overseas Finance Limited; and\n(b)shall for the purposes of section 14I of the Act be treated as having been allowed to United Overseas Bank Limited as a deduction under that section,\nsubject to the conditions specified in the letter of approval dated 12th July 2000."}}],"pack":"sg-p32","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Transfer of Undertaking by Bank or Finance Company) (No. 10) Order 2000","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2559"] = {"id":"SG-H2559","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S116-2000?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（银行或金融公司业务转让）（第 2 号）命令 2000","en":"Income Tax (Transfer of Undertaking by Bank or Finance Company) (No. 2) Order 2000","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S116-2000","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2559-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order may be cited as the Income Tax (Transfer of Undertaking by Bank or Finance Company) (No. 2) Order 2000."}},{"id":"SG-H2559-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Declaration of provisions in accounts"},"text":{"en":"2. It is hereby declared that under section 14I(3) of the Act, the provisions in the account of The Bank of Tokyo Ltd. which have been transferred to The Bank of Tokyo-Mitsubishi Ltd. —\n(a)shall not be deemed under section 14I(2)(b) of the Act to be a trading receipt of The Bank of Tokyo Ltd.; and\n(b)shall for the purposes of section 14I of the Act be treated as having been allowed to The Bank of Tokyo-Mitsubishi Ltd. as a deduction under that section,\nsubject to the conditions specified in the letter of approval dated 28th February 2000."}}],"pack":"sg-p32","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Transfer of Undertaking by Bank or Finance Company) (No. 2) Order 2000","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2560"] = {"id":"SG-H2560","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S125-2001?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（银行或金融公司业务转让）（第 2 号）命令 2001","en":"Income Tax (Transfer of Undertaking by Bank or Finance Company) (No. 2) Order 2001","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S125-2001","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2560-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order may be cited as the Income Tax (Transfer of Undertaking by Bank or Finance Company) (No. 2) Order 2001."}},{"id":"SG-H2560-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Declaration of provisions in accounts"},"text":{"en":"2. It is hereby declared that under section 14I(3) of the Act, the provisions in the accounts of DBS Finance Limited which have been transferred to Development Bank of Singapore Limited —\n(a)shall not be deemed under section 14I(2)(b) of the Act to be a trading receipt of DBS Finance Limited; and\n(b)shall for the purposes of section 14I of the Act be treated as having been allowed to Development Bank of Singapore Limited as a deduction under that section,\nsubject to the conditions specified in the letter of approval dated 24th November 2000."}}],"pack":"sg-p32","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Transfer of Undertaking by Bank or Finance Company) (No. 2) Order 2001","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2561"] = {"id":"SG-H2561","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S665-2002?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（银行或金融公司业务转让）（第 2 号）命令 2002","en":"Income Tax (Transfer of Undertaking by Bank or Finance Company) (No. 2) Order 2002","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S665-2002","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2561-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order may be cited as the Income Tax (Transfer of Undertaking by Bank or Finance Company) (No. 2) Order 2002."}},{"id":"SG-H2561-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Declaration of provisions in accounts"},"text":{"en":"2. It is hereby declared that, subject to the conditions specified in the letter of approval dated 23rd July 2001, the provisions in the accounts of The Sakura Bank Limited Singapore Branch which have been transferred to Sumitomo Mitsui Banking Corporation Singapore Branch —\n(a)shall not be deemed under section 14I(2)(b) of the Act to be a trading receipt of The Sakura Bank Limited Singapore Branch; and\n(b)shall for the purposes of section 14I of the Act be treated as having been allowed to Sumitomo Mitsui Banking Corporation Singapore Branch as a deduction under that section."}}],"pack":"sg-p32","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Transfer of Undertaking by Bank or Finance Company) (No. 2) Order 2002","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2562"] = {"id":"SG-H2562","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S493-2003?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（银行或金融公司业务转让）（第 2 号）命令 2003","en":"Income Tax (Transfer of Undertaking by Bank or Finance Company) (No. 2) Order 2003","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S493-2003","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2562-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order may be cited as the Income Tax (Transfer of Undertaking by Bank or Finance Company) (No. 2) Order 2003."}},{"id":"SG-H2562-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Declaration of provisions in accounts"},"text":{"en":"2. It is hereby declared that, subject to the conditions specified in the letter of approval dated 10th October 2003, the provisions in the accounts of Bank Brussels Lambert Singapore Branch which have been transferred to ING Bank N.V. Singapore Branch —\n(a)shall not be deemed under section 14I(2)(b) of the Act to be a trading receipt of Bank Brussels Lambert Singapore Branch; and\n(b)shall for the purposes of section 14I of the Act be treated as having been allowed to ING Bank N.V. Singapore Branch as a deduction under that section."}}],"pack":"sg-p32","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Transfer of Undertaking by Bank or Finance Company) (No. 2) Order 2003","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2563"] = {"id":"SG-H2563","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S610-2006?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":11,"structureMode":"ARTICLE","title":{"zh":"所得税（银行或金融公司转让营业）（第二号）命令 2006","en":"Income Tax (Transfer of Undertaking by Bank or Finance Company) (No. 2) Order 2006","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S610-2006","completenessNote":"全文，共 11 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2563-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order may be cited as the Income Tax (Transfer of Undertaking by Bank or Finance Company) (No. 2) Order 2006."}},{"id":"SG-H2563-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Declaration of provisions in accounts of Banca Commerciale Italiana Singapore Branch"},"text":{"en":"2. It is hereby declared that, subject to the conditions specified in the letter of approval dated 9th October 2006, the provisions in the accounts of Banca Commerciale Italiana Singapore Branch which have been transferred to Banca Intesa S.P.A. Singapore Branch —\n(a)shall not be deemed under section 14I(2)(b) of the Act to be a trading receipt of Banca Commerciale Italiana Singapore Branch; and\n(b)shall for the purposes of section 14I of the Act be treated as having been allowed to Banca Intesa S.P.A. Singapore Branch as a deduction under that section."}},{"id":"SG-H2563-A3","no":3,"noLabel":{"en":"3."},"heading":{"en":"Declaration of provisions in accounts of The Industrial Bank of Japan Limited Singapore Branch"},"text":{"en":"3. It is hereby declared that, subject to the conditions specified in the letter of approval dated 9th October 2006, the provisions in the accounts of The Industrial Bank of Japan Limited Singapore Branch which have been transferred to Mizuho Corporate Bank Limited Singapore Branch —\n(a)shall not be deemed under section 14I(2)(b) of the Act to be a trading receipt of The Industrial Bank of Japan Limited Singapore Branch; and\n(b)shall for the purposes of section 14I of the Act be treated as having been allowed to Mizuho Corporate Bank Limited Singapore Branch as a deduction under that section."}},{"id":"SG-H2563-A4","no":4,"noLabel":{"en":"4."},"heading":{"en":"Declaration of provisions in accounts of Sumitomo Mitsui Banking Corporation Singapore Branch"},"text":{"en":"4. It is hereby declared that, subject to the conditions specified in the letter of approval dated 9th October 2006, the provisions in the accounts of Sumitomo Mitsui Banking Corporation Singapore Branch (Registration No. F02256K) which have been transferred to Sumitomo Mitsui Banking Corporation Singapore Branch (Registration No. F06366D) —\n(a)shall not be deemed under section 14I(2)(b) of the Act to be a trading receipt of Sumitomo Mitsui Banking Corporation Singapore Branch (Registration No. F02256K); and\n(b)shall for the purposes of section 14I of the Act be treated as having been allowed to Sumitomo Mitsui Banking Corporation Singapore Branch (Registration No. F06366D) as a deduction under that section."}},{"id":"SG-H2563-A5","no":5,"noLabel":{"en":"5."},"heading":{"en":"Declaration of provisions in accounts of Nordea Bank Finland Plc Singapore Branch"},"text":{"en":"5. It is hereby declared that, subject to the conditions specified in the letter of approval dated 9th October 2006, the provisions in the accounts of Nordea Bank Finland Plc Singapore Branch (Registration No. F06157M) which have been transferred to Nordea Bank Finland Plc Singapore Branch (Registration No. F06200G) —\n(a)shall not be deemed under section 14I(2)(b) of the Act to be a trading receipt of Nordea Bank Finland Plc Singapore Branch (Registration No. F06157M); and\n(b)shall for the purposes of section 14I of the Act be treated as having been allowed to Nordea Bank Finland Plc Singapore Branch (Registration No. F06200G) as a deduction under that section."}},{"id":"SG-H2563-A6","no":6,"noLabel":{"en":"6."},"heading":{"en":"Declaration of provisions in accounts of Industrial & Commercial Bank Ltd"},"text":{"en":"6. It is hereby declared that, subject to the conditions specified in the letter of approval dated 9th October 2006, the provisions in the accounts of Industrial & Commercial Bank Ltd which have been transferred to United Overseas Bank Ltd —\n(a)shall not be deemed under section 14I(2)(b) of the Act to be a trading receipt of Industrial & Commercial Bank Ltd; and\n(b)shall for the purposes of section 14I of the Act be treated as having been allowed to United Overseas Bank Ltd as a deduction under that section."}},{"id":"SG-H2563-A7","no":7,"noLabel":{"en":"7."},"heading":{"en":"Declaration of provisions in accounts of Overseas Union Trust Ltd"},"text":{"en":"7. It is hereby declared that, subject to the conditions specified in the letter of approval dated 9th October 2006, the provisions in the accounts of Overseas Union Trust Ltd which have been transferred to United Overseas Bank Ltd —\n(a)shall not be deemed under section 14I(2)(b) of the Act to be a trading receipt of Overseas Union Trust Ltd; and\n(b)shall for the purposes of section 14I of the Act be treated as having been allowed to United Overseas Bank Ltd as a deduction under that section."}},{"id":"SG-H2563-A8","no":8,"noLabel":{"en":"8."},"heading":{"en":"Declaration of provisions in accounts of Keppel TatLee Finance Limited"},"text":{"en":"8. It is hereby declared that, subject to the conditions specified in the letter of approval dated 9th October 2006, the provisions in the accounts of Keppel TatLee Finance Limited which have been transferred to OCBC Finance Limited —\n(a)shall not be deemed under section 14I(2)(b) of the Act to be a trading receipt of Keppel TatLee Finance Limited; and\n(b)shall for the purposes of section 14I of the Act be treated as having been allowed to OCBC Finance Limited as a deduction under that section."}},{"id":"SG-H2563-A9","no":9,"noLabel":{"en":"9."},"heading":{"en":"Declaration of provisions in accounts of Keppel TatLee Bank Limited"},"text":{"en":"9. It is hereby declared that, subject to the conditions specified in the letter of approval dated 9th October 2006, the provisions in the accounts of Keppel TatLee Bank Limited which have been transferred to Oversea-Chinese Banking Corporation Limited —\n(a)shall not be deemed under section 14I(2)(b) of the Act to be a trading receipt of Keppel TatLee Bank Limited; and\n(b)shall for the purposes of section 14I of the Act be treated as having been allowed to Oversea-Chinese Banking Corporation Limited as a deduction under that section."}},{"id":"SG-H2563-A10","no":10,"noLabel":{"en":"10."},"heading":{"en":"Declaration of provisions in accounts of OCBC Finance Limited"},"text":{"en":"10. It is hereby declared that, subject to the conditions specified in the letter of approval dated 9th October 2006, the provisions in the accounts of OCBC Finance Limited which have been transferred to Oversea-Chinese Banking Corporation Limited —\n(a)shall not be deemed under section 14I(2)(b) of the Act to be a trading receipt of OCBC Finance Limited; and\n(b)shall for the purposes of section 14I of the Act be treated as having been allowed to Oversea-Chinese Banking Corporation Limited as a deduction under that section."}},{"id":"SG-H2563-A11","no":11,"noLabel":{"en":"11."},"heading":{"en":"Declaration of provisions in accounts of MeritaNordbanken Merchant Bank Singapore Limited"},"text":{"en":"11. It is hereby declared that, subject to the conditions specified in the letter of approval dated 9th October 2006, the provisions in the accounts of MeritaNordbanken Merchant Bank Singapore Limited which have been transferred to Nordea Bank Finland Plc Singapore Branch —\n(a)shall not be deemed under section 14I(2)(b) of the Act to be a trading receipt of MeritaNordbanken Merchant Bank Singapore Limited; and\n(b)shall for the purposes of section 14I of the Act be treated as having been allowed to Nordea Bank Finland Plc Singapore Branch as a deduction under that section."}}],"pack":"sg-p32","titleTranslation":{"engine":"manual-llm","reviewed":false,"source":"Income Tax (Transfer of Undertaking by Bank or Finance Company) (No. 2) Order 2006","note":"人工逐条翻译（模型产出，未经人工复核）；公司名、地名、机构名保留原文。"}};
  FT["SG-H2564"] = {"id":"SG-H2564","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S652-2010?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（银行或金融公司业务转让）（第 2 号）命令 2010","en":"Income Tax (Transfer of Undertaking by Bank or Finance Company) (No. 2) Order 2010","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S652-2010","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2564-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order may be cited as the Income Tax (Transfer of Undertaking by Bank or Finance Company) (No. 2) Order 2010."}},{"id":"SG-H2564-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Declaration of provisions in accounts"},"text":{"en":"2. It is hereby declared that, subject to the conditions specified in the letter of approval dated 5th October 2010, the provisions in the accounts of Hana Bank Singapore Branch (ACRA Registration No. T00FC5901B) which have been transferred to Hana Bank Singapore Branch (ACRA Registration No. T03FC6382K) —\n(a)shall not be deemed under section 14I(2)(b) of the Act to be a trading receipt of Hana Bank Singapore Branch (ACRA Registration No. T00FC5901B); and\n(b)shall for the purposes of section 14I of the Act be treated as having been allowed to Hana Bank Singapore Branch (ACRA Registration No. T03FC6382K) as a deduction under that section."}}],"pack":"sg-p32","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Transfer of Undertaking by Bank or Finance Company) (No. 2) Order 2010","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2565"] = {"id":"SG-H2565","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S148-2000?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（银行或金融公司业务转让）（第 3 号）命令 2000","en":"Income Tax (Transfer of Undertaking by Bank or Finance Company) (No. 3) Order 2000","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S148-2000","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2565-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order may be cited as the Income Tax (Transfer of Undertaking by Bank or Finance Company) (No. 3) Order 2000."}},{"id":"SG-H2565-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Declaration of provisions in accounts"},"text":{"en":"2. It is hereby declared that under section 14I(3) of the Act, the provisions in the accounts of the Union Bank of Switzerland and Swiss Bank Corporation which have been transferred to UBS AG —\n(a)shall not be deemed under section 14I(2)(b) of the Act to be trading receipts of the Union Bank of Switzerland and Swiss Bank Corporation; and\n(b)shall for the purposes of section 14I of the Act be treated as having been allowed to UBS AG as a deduction under that section,\nsubject to the conditions specified in the letter of approval dated 28th February 2000."}}],"pack":"sg-p32","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Transfer of Undertaking by Bank or Finance Company) (No. 3) Order 2000","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2566"] = {"id":"SG-H2566","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S127-2001?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（银行或金融公司业务转让）（第 3 号）命令 2001","en":"Income Tax (Transfer of Undertaking by Bank or Finance Company) (No. 3) Order 2001","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S127-2001","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2566-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order may be cited as the Income Tax (Transfer of Undertaking by Bank or Finance Company) (No. 3) Order 2001."}},{"id":"SG-H2566-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Declaration of provisions in accounts"},"text":{"en":"2. It is hereby declared that under section 14I(3) of the Act, the provisions in the accounts of Bank of Singapore Limited which have been transferred to Oversea-Chinese Banking Corporation Limited —\n(a)shall not be deemed under section 14I(2)(b) of the Act to be a trading receipt of Bank of Singapore Limited; and\n(b)shall for the purposes of section 14I of the Act be treated as having been allowed to Oversea-Chinese Banking Corporation Limited as a deduction under that section,\nsubject to the conditions specified in the letter of approval dated 8th January 2001."}}],"pack":"sg-p32","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Transfer of Undertaking by Bank or Finance Company) (No. 3) Order 2001","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2567"] = {"id":"SG-H2567","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S666-2002?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（银行或金融公司业务转让）（第 3 号）命令 2002","en":"Income Tax (Transfer of Undertaking by Bank or Finance Company) (No. 3) Order 2002","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S666-2002","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2567-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order may be cited as the Income Tax (Transfer of Undertaking by Bank or Finance Company) (No. 3) Order 2002."}},{"id":"SG-H2567-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Declaration of provisions in accounts"},"text":{"en":"2. It is hereby declared that, subject to the conditions specified in the letter of approval dated 24th April 2002, the provisions in the accounts of Four Seas Bank Limited which have been transferred to Overseas-Chinese Banking Corporation Limited —\n(a)shall not be deemed under section 14I(2)(b) of the Act to be a trading receipt of Four Seas Bank Limited; and\n(b)shall for the purposes of section 14I of the Act be treated as having been allowed to Overseas-Chinese Banking Corporation Limited as a deduction under that section."}}],"pack":"sg-p32","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Transfer of Undertaking by Bank or Finance Company) (No. 3) Order 2002","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2568"] = {"id":"SG-H2568","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S401-2000?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（银行或金融公司业务转让）（第 4 号）命令 2000","en":"Income Tax (Transfer of Undertaking by Bank or Finance Company) (No. 4) Order 2000","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S401-2000","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2568-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order may be cited as the Income Tax (Transfer of Undertaking by Bank or Finance Company) (No. 4) Order 2000."}},{"id":"SG-H2568-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Declaration of provisions in accounts"},"text":{"en":"2. It is hereby declared that under section 14I(3) of the Act, the provisions in the account of Bank Austria AG and Creditanstalt AG which have been transferred to Bank Austria Creditanstalt International AG —\n(a)shall not be deemed under section 14I(2)(b) of the Act to be trading receipts of Bank Austria AG and Creditanstalt AG; and\n(b)shall for the purposes of section 14I of the Act be treated as having been allowed to Bank Austria Creditanstalt International AG as a deduction under that section,\nsubject to the conditions specified in the letter of approval dated 21st March 2000."}}],"pack":"sg-p32","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Transfer of Undertaking by Bank or Finance Company) (No. 4) Order 2000","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H2569"] = {"id":"SG-H2569","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S667-2002?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（银行或金融公司业务转让）（第 4 号）命令 2002","en":"Income Tax (Transfer of Undertaking by Bank or Finance Company) (No. 4) Order 2002","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S667-2002","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2569-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order may be cited as the Income Tax (Transfer of Undertaking by Bank or Finance Company) (No. 4) Order 2002."}},{"id":"SG-H2569-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Declaration of provisions in accounts"},"text":{"en":"2. It is hereby declared that, subject to the conditions specified in the letter of approval dated 8th June 2002, the provisions in the accounts of International Bank of Singapore Limited which have been transferred to Overseas Union Bank Limited —\n(a)shall not be deemed under section 14I(2)(b) of the Act to be a trading receipt of International Bank of Singapore Limited; and\n(b)shall for the purposes of section 14I of the Act be treated as having been allowed to Overseas Union Bank Limited as a deduction under that section."}}],"pack":"sg-p32","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Transfer of Undertaking by Bank or Finance Company) (No. 4) Order 2002","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
