  FT["SG-H2577"] = {"id":"SG-H2577","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S209-1999?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（银行或金融公司业务转让）命令 1999","en":"Income Tax (Transfer of Undertaking by Bank or Finance Company) Order 1999","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S209-1999","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2577-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order may be cited as the Income Tax (Transfer of Undertaking by Bank or Finance Company) Order 1999."}},{"id":"SG-H2577-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Declaration of provisions in accounts"},"text":{"en":"2. It is hereby declared that pursuant to section 14I(3) of the Act, the provisions in the account of the Chase Manhattan Bank, N.A. which have been transferred to the Chase Manhattan Bank (formerly known as Chemical Bank) —\n(a)shall not be deemed under section 14I(2)(b) of the Act to be a trading receipt of the Chase Manhattan Bank, N.A.; and\n(b)shall for the purposes of section 14I of the Act be treated as having been allowed to the Chase Manhattan Bank (formerly known as Chemical Bank) as a deduction under that section,\nsubject to the conditions specified in the letter of approval dated 2nd January 1999."}}],"pack":"sg-p32","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Transfer of Undertaking by Bank or Finance Company) Order 1999","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
